import React, { useCallback, useEffect, useState } from 'react';
import {
  Box,
  Collapse,
  Divider,
  Drawer,
  List,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Typography,
  useMediaQuery,
} from '@mui/material';
import { useTheme } from '@mui/material/styles';
import {
  Assessment as CarbonAssessmentNavIcon,
  Description as DocumentsNavIcon,
  ExpandLess,
  ExpandMore,
  HelpOutline as HelpIcon,
  Home as HomeNavIcon,
  InfoOutlined as InfoIcon,
  Security as PrivacyIcon,
  Badge as ProfileNavIcon,
  Settings as SettingsNavIcon,
  Summarize as ReportsNavIcon,
  Gavel as ComplianceNavIcon,
  TrendingDown as EmissionsTargetsNavIcon,
} from '@mui/icons-material';
import { useLocation, useNavigate } from 'react-router-dom';
import {
  isEnterpriseAppPath,
  isNavPathActive,
  isTopicActive,
  NavTopic,
  PRIMARY_NAV_TOPICS,
  SECONDARY_NAV_TOPICS,
  SIDEBAR_WIDTH,
} from '../constants/appNavigation';
import {
  ENTERPRISE_PRIMARY_NAV_TOPICS,
  ENTERPRISE_SECONDARY_NAV_TOPICS,
} from '../constants/enterpriseNavigation';

const TOPIC_ICONS: Record<string, React.ReactElement> = {
  Home: <HomeNavIcon fontSize="small" />,
  'My company': <ProfileNavIcon fontSize="small" />,
  Data: <DocumentsNavIcon fontSize="small" />,
  'Carbon Assessment': <CarbonAssessmentNavIcon fontSize="small" />,
  'Emissions targets': <EmissionsTargetsNavIcon fontSize="small" />,
  Compliance: <ComplianceNavIcon fontSize="small" />,
  Reports: <ReportsNavIcon fontSize="small" />,
  Information: <InfoIcon fontSize="small" />,
  'Data Privacy': <PrivacyIcon fontSize="small" />,
  Settings: <SettingsNavIcon fontSize="small" />,
  'Help Center': <HelpIcon fontSize="small" />,
};

interface AppSidebarProps {
  mobileOpen?: boolean;
  onMobileClose?: () => void;
}

const AppSidebar: React.FC<AppSidebarProps> = ({ mobileOpen = false, onMobileClose }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const mode = theme.palette.mode;
  const isEnterprise = isEnterpriseAppPath(location.pathname);
  const primaryTopics = isEnterprise ? ENTERPRISE_PRIMARY_NAV_TOPICS : PRIMARY_NAV_TOPICS;
  const secondaryTopics = isEnterprise ? ENTERPRISE_SECONDARY_NAV_TOPICS : SECONDARY_NAV_TOPICS;

  const [expandedTopics, setExpandedTopics] = useState<Record<string, boolean>>(() => {
    const initial: Record<string, boolean> = {};
    primaryTopics.forEach((topic) => {
      if (topic.children?.length && isTopicActive(location.pathname, location.search, topic)) {
        initial[topic.path] = true;
      }
    });
    return initial;
  });

  useEffect(() => {
    primaryTopics.forEach((topic) => {
      if (topic.children?.length && isTopicActive(location.pathname, location.search, topic)) {
        setExpandedTopics((prev) => ({ ...prev, [topic.path]: true }));
      }
    });
  }, [location.pathname, location.search, primaryTopics]);

  const handleNavigate = useCallback(
    (path: string) => {
      navigate(path);
      onMobileClose?.();
    },
    [navigate, onMobileClose]
  );

  const toggleTopic = (topic: NavTopic) => {
    if (!topic.children?.length) {
      handleNavigate(topic.path);
      return;
    }

    const topicActive = isTopicActive(location.pathname, location.search, topic);
    const isExpanded = expandedTopics[topic.path] ?? topicActive;

    if (topicActive && isExpanded) {
      return;
    }

    setExpandedTopics((prev) => ({
      ...prev,
      [topic.path]: !isExpanded,
    }));

    if (!topicActive) {
      handleNavigate(topic.children[0].path);
    }
  };

  const navItemStyles = (active: boolean) => ({
    borderRadius: 1.5,
    mx: 1,
    mb: 0.25,
    transition: 'background-color 0.2s ease',
    backgroundColor: active
      ? mode === 'light'
        ? 'rgba(76, 175, 80, 0.12)'
        : 'rgba(76, 175, 80, 0.2)'
      : 'transparent',
    '&:hover': {
      backgroundColor: active
        ? mode === 'light'
          ? 'rgba(76, 175, 80, 0.16)'
          : 'rgba(76, 175, 80, 0.26)'
        : mode === 'light'
          ? 'rgba(15, 23, 42, 0.05)'
          : 'rgba(255, 255, 255, 0.06)',
    },
  });

  const renderTopic = (topic: NavTopic) => {
    const hasChildren = Boolean(topic.children?.length);
    const topicActive = isTopicActive(location.pathname, location.search, topic);
    const isExpanded = expandedTopics[topic.path] ?? topicActive;

    return (
      <React.Fragment key={topic.path}>
        <ListItemButton
          onClick={() => toggleTopic(topic)}
          selected={topicActive && !hasChildren}
          sx={navItemStyles(topicActive)}
          aria-expanded={hasChildren ? isExpanded : undefined}
          aria-current={topicActive && !hasChildren ? 'page' : undefined}
        >
          <ListItemIcon sx={{ minWidth: 36, color: topicActive ? 'primary.main' : 'text.secondary' }}>
            {TOPIC_ICONS[topic.label] ?? <HomeNavIcon fontSize="small" />}
          </ListItemIcon>
          <ListItemText
            primary={topic.label}
            primaryTypographyProps={{
              fontSize: '0.875rem',
              fontWeight: topicActive ? 600 : 500,
            }}
          />
          {hasChildren ? (isExpanded ? <ExpandLess fontSize="small" /> : <ExpandMore fontSize="small" />) : null}
        </ListItemButton>

        {hasChildren && (
          <Collapse in={isExpanded} timeout="auto" unmountOnExit>
            <List dense disablePadding sx={{ pl: 2, pb: 0.5 }}>
              {topic.children!.map((child) => {
                const childActive = isNavPathActive(
                  location.pathname,
                  location.search,
                  child.path
                );
                return (
                  <ListItemButton
                    key={child.path}
                    onClick={() => handleNavigate(child.path)}
                    selected={childActive}
                    sx={{
                      ...navItemStyles(childActive),
                      py: 0.5,
                      pl: 3,
                    }}
                    aria-current={childActive ? 'page' : undefined}
                  >
                    <ListItemText
                      primary={child.label}
                      primaryTypographyProps={{
                        fontSize: '0.8125rem',
                        fontWeight: childActive ? 600 : 400,
                        color: childActive ? 'text.primary' : 'text.secondary',
                      }}
                    />
                  </ListItemButton>
                );
              })}
            </List>
          </Collapse>
        )}
      </React.Fragment>
    );
  };

  const sidebarContent = (
    <Box
      sx={{
        width: SIDEBAR_WIDTH,
        height: '100%',
        display: 'flex',
        flexDirection: 'column',
        pt: 2,
        pb: 2,
        minHeight: 0,
      }}
    >
      <Typography
        id="app-sidebar-workspace-heading"
        variant="overline"
        sx={{ px: 2.5, mb: 1, flexShrink: 0, fontWeight: 700, letterSpacing: 1.2, color: 'text.secondary' }}
      >
        Workspace
      </Typography>
      <List
        component="nav"
        aria-labelledby="app-sidebar-workspace-heading"
        disablePadding
        sx={{ flex: 1, minHeight: 0, overflowY: 'auto', px: 0 }}
      >
        {primaryTopics.map((topic) => renderTopic(topic))}
      </List>

      <Divider sx={{ mx: 2, my: 1, flexShrink: 0 }} />

      <Typography
        id="app-sidebar-more-heading"
        variant="overline"
        sx={{ px: 2.5, mb: 0.5, flexShrink: 0, fontWeight: 700, letterSpacing: 1.2, color: 'text.secondary' }}
      >
        More
      </Typography>
      <List dense disablePadding aria-labelledby="app-sidebar-more-heading" sx={{ flexShrink: 0 }}>
        {secondaryTopics.map((topic) => {
          const topicActive = isTopicActive(location.pathname, location.search, topic);
          return (
            <ListItemButton
              key={topic.path}
              onClick={() => handleNavigate(topic.path)}
              selected={topicActive}
              sx={navItemStyles(topicActive)}
              aria-current={topicActive ? 'page' : undefined}
            >
              <ListItemIcon
                sx={{
                  minWidth: 36,
                  color: topicActive ? 'primary.main' : 'text.secondary',
                }}
              >
                {TOPIC_ICONS[topic.label]}
              </ListItemIcon>
              <ListItemText
                primary={topic.label}
                primaryTypographyProps={{
                  fontSize: '0.875rem',
                  fontWeight: topicActive ? 600 : 500,
                }}
              />
            </ListItemButton>
          );
        })}
      </List>
    </Box>
  );

  if (isMobile) {
    return (
      <Drawer
        variant="temporary"
        open={mobileOpen}
        onClose={onMobileClose}
        ModalProps={{ keepMounted: true }}
        sx={{
          display: { xs: 'block', md: 'none' },
          '& .MuiDrawer-paper': {
            width: SIDEBAR_WIDTH,
            boxSizing: 'border-box',
            borderRight: '1px solid',
            borderColor: 'divider',
          },
        }}
      >
        <Box component="nav" aria-label="Main navigation">
          {sidebarContent}
        </Box>
      </Drawer>
    );
  }

  return (
    <Box
      component="nav"
      aria-label="Main navigation"
      sx={{
        width: SIDEBAR_WIDTH,
        flexShrink: 0,
        display: { xs: 'none', md: 'flex' },
        flexDirection: 'column',
        alignSelf: 'stretch',
        minHeight: 0,
        borderRight: '1px solid',
        borderColor: 'divider',
        bgcolor: 'background.paper',
      }}
    >
      {sidebarContent}
    </Box>
  );
};

export default AppSidebar;
