import React, { useState, useEffect } from 'react';
import {
    Box,
    Container,
    Typography,
    Grid,
    Card,
    CardContent,
    Button,
    TextField,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    Chip,
    Alert,
    CircularProgress,
    Tab,
    Tabs,
    InputAdornment,
} from '@mui/material';
import { useTheme } from '@mui/material/styles';
import {
    TrendingUp,
    ShoppingCart,
    AccountBalance,
    History,
    Add,
    Remove,
} from '@mui/icons-material';
import {
    ComposedChart,
    Line,
    Area,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip,
    Legend,
    ResponsiveContainer,
} from 'recharts';
import {
    axisTickForMode,
    cartesianGridStroke,
    chartAnimationProps,
    rechartsLegendProps,
    rechartsTooltipProps,
} from '../theme/rechartsAppearances';
import api from '../services/api';
import TabSectionNavLinks from './TabSectionNavLinks';

const CARBON_TRADING_TAB_LABELS = ['Market', 'Price History', 'Trade History'] as const;

interface CarbonCredit {
    _id: string;
    msme: string;
    totalCredits: number;
    availableCredits: number;
    usedCredits: number;
    pricePerCredit: number;
    status: string;
}

interface ApiCarbonTradingPortfolio {
    totalCredits: number;
    availableCredits: number;
    usedCredits: number;
    averagePrice: number;
}

interface Trade {
    _id: string;
    type: 'purchase' | 'offset' | 'transfer' | 'refund';
    credits: number;
    pricePerCredit: number;
    totalAmount: number;
    status: string;
    createdAt: string;
}

interface MarketListing {
    _id: string;
    seller?: string;
    name?: string;
    credits: number;
    pricePerCredit: number;
    totalValue?: number;
    availableCredits?: number;
    status: string;
    verifiedBy?: string;
    location?: {
        city?: string;
        state?: string;
        country?: string;
    };
    createdAt?: string;
}

const CarbonTrading: React.FC = () => {
    const theme = useTheme();
    const isDark = theme.palette.mode === 'dark';
    const gridStroke = cartesianGridStroke(isDark);
    const tickStyle = axisTickForMode(isDark);
    const tipProps = rechartsTooltipProps(isDark);

    const [tabValue, setTabValue] = useState(0);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [success, setSuccess] = useState<string | null>(null);

    // State for carbon credits
    const [carbonCredits, setCarbonCredits] = useState<CarbonCredit | null>(null);
    const [tradeHistory, setTradeHistory] = useState<Trade[]>([]);
    const [marketListings, setMarketListings] = useState<MarketListing[]>([]);
    const [priceHistory, setPriceHistory] = useState<any[]>([]);

    // Dialog states
    const [buyDialogOpen, setBuyDialogOpen] = useState(false);
    const [sellDialogOpen, setSellDialogOpen] = useState(false);
    const [selectedListing, setSelectedListing] = useState<MarketListing | null>(null);

    // Form states
    const [buyAmount, setBuyAmount] = useState('');
    const [sellAmount, setSellAmount] = useState('');
    const [sellPrice, setSellPrice] = useState('');

    useEffect(() => {
        fetchCarbonCredits();
        fetchTradeHistory();
        fetchMarketListings();
        fetchPriceHistory();
    }, []);

    const fetchCarbonCredits = async () => {
        try {
            setLoading(true);
            setError(null);
            const response = await api.getCarbonTradingPortfolio() as { data?: ApiCarbonTradingPortfolio };
            setCarbonCredits({
                _id: 'portfolio',
                msme: 'current',
                totalCredits: response?.data?.totalCredits || 0,
                availableCredits: response?.data?.availableCredits || 0,
                usedCredits: response?.data?.usedCredits || 0,
                pricePerCredit: response?.data?.averagePrice || 0,
                status: 'active',
            });
        } catch (err: any) {
            setError(err.message || 'Failed to fetch carbon credits');
        } finally {
            setLoading(false);
        }
    };

    const fetchTradeHistory = async () => {
        try {
            const response = await api.getCarbonTradingHistory({ limit: 100 });
            const rawHistory = response?.data?.transactions || [];
            const normalizedHistory: Trade[] = rawHistory.map((entry: any) => ({
                _id: entry._id || `${entry.type}_${entry.timestamp}`,
                type: entry.type || 'purchase',
                credits: Number(entry.amount || 0),
                pricePerCredit: Number(entry.pricePerTon || 0),
                totalAmount: Number(entry.totalCost || 0),
                status: entry.status || 'completed',
                createdAt: entry.timestamp || new Date().toISOString(),
            }));
            setTradeHistory(normalizedHistory);
        } catch (err: any) {
            console.error('Failed to fetch trade history:', err);
        }
    };

    const fetchMarketListings = async () => {
        try {
            const response = await api.getCarbonOffsetOptions({ limit: 100 });
            const rawListings = response?.data || [];
            const normalizedListings: MarketListing[] = rawListings.map((listing: any) => ({
                _id: listing._id,
                seller: listing.verifiedBy || 'Verified Registry',
                name: listing.name,
                credits: Number(listing.availableCredits || 0),
                availableCredits: Number(listing.availableCredits || 0),
                pricePerCredit: Number(listing.pricePerTon || 0),
                totalValue: Number((listing.availableCredits || 0) * (listing.pricePerTon || 0)),
                status: listing.isActive ? 'active' : 'inactive',
                verifiedBy: listing.verifiedBy,
                location: typeof listing.location === 'string' ? { city: listing.location } : listing.location,
                createdAt: listing.createdAt,
            }));
            setMarketListings(normalizedListings);
        } catch (err: any) {
            console.error('Failed to fetch market listings:', err);
        }
    };

    const fetchPriceHistory = async () => {
        try {
            const response = await api.getCarbonOffsetOptions({ limit: 200 });
            const rawListings = response?.data || [];
            const grouped = rawListings.reduce((acc: Record<string, { total: number; count: number }>, listing: any) => {
                const date = new Date(listing.createdAt || Date.now()).toISOString().slice(0, 10);
                if (!acc[date]) {
                    acc[date] = { total: 0, count: 0 };
                }
                acc[date].total += Number(listing.pricePerTon || 0);
                acc[date].count += 1;
                return acc;
            }, {});
            const chartData = Object.entries(grouped)
                .sort((a, b) => a[0].localeCompare(b[0]))
                .map(([date, metrics]) => ({
                    date,
                    price: Number((metrics.total / Math.max(metrics.count, 1)).toFixed(2)),
                }));
            setPriceHistory(chartData);
        } catch (err: any) {
            console.error('Failed to fetch price history:', err);
        }
    };

    const handleBuyCredits = async () => {
        if (!selectedListing || !buyAmount) return;

        try {
            setLoading(true);
            setError(null);
            await api.purchaseCarbonOffset({
                offsetId: selectedListing._id,
                amount: Number(buyAmount),
                pricePerTon: selectedListing.pricePerCredit,
            });
            setSuccess('Successfully purchased carbon credits!');
            setBuyDialogOpen(false);
            setBuyAmount('');
            setSelectedListing(null);
            fetchCarbonCredits();
            fetchTradeHistory();
            fetchMarketListings();
        } catch (err: any) {
            setError(err.message || 'Failed to buy credits');
        } finally {
            setLoading(false);
        }
    };

    const handleSellCredits = async () => {
        if (!sellAmount || !sellPrice) return;

        try {
            setLoading(true);
            setError(null);
            await api.offsetCarbonCredits({
                amount: Number(sellAmount),
                description: `Credits retired via web dashboard at $${Number(sellPrice).toFixed(2)} per credit reference`,
            });
            setSuccess('Successfully retired carbon credits!');
            setSellDialogOpen(false);
            setSellAmount('');
            setSellPrice('');
            fetchCarbonCredits();
            fetchMarketListings();
        } catch (err: any) {
            setError(err.message || 'Failed to sell credits');
        } finally {
            setLoading(false);
        }
    };

    const openBuyDialog = (listing: MarketListing) => {
        setSelectedListing(listing);
        setBuyDialogOpen(true);
    };

    return (
        <Container maxWidth="xl">
            <Box sx={{ py: 4 }}>
                {/* Header */}
                <Box sx={{ mb: 4 }}>
                    <Typography variant="h4" gutterBottom fontWeight="bold">
                        Carbon Credit Trading
                    </Typography>
                    <Typography variant="body1" color="text.secondary">
                        Buy and sell carbon credits in the marketplace
                    </Typography>
                </Box>

                {/* Alerts */}
                {error && (
                    <Alert severity="error" onClose={() => setError(null)} sx={{ mb: 2 }}>
                        {error}
                    </Alert>
                )}
                {success && (
                    <Alert severity="success" onClose={() => setSuccess(null)} sx={{ mb: 2 }}>
                        {success}
                    </Alert>
                )}

                {/* Overview Cards */}
                <Grid container spacing={3} sx={{ mb: 4 }}>
                    <Grid item xs={12} md={3}>
                        <Card>
                            <CardContent>
                                <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                                    <AccountBalance color="primary" sx={{ mr: 1 }} />
                                    <Typography variant="h6">Total Credits</Typography>
                                </Box>
                                <Typography variant="h4" fontWeight="bold">
                                    {carbonCredits?.totalCredits?.toFixed(2) || '0.00'}
                                </Typography>
                                <Typography variant="caption" color="text.secondary">
                                    Carbon credits owned
                                </Typography>
                            </CardContent>
                        </Card>
                    </Grid>

                    <Grid item xs={12} md={3}>
                        <Card>
                            <CardContent>
                                <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                                    <ShoppingCart color="success" sx={{ mr: 1 }} />
                                    <Typography variant="h6">Available</Typography>
                                </Box>
                                <Typography variant="h4" fontWeight="bold" color="success.main">
                                    {carbonCredits?.availableCredits?.toFixed(2) || '0.00'}
                                </Typography>
                                <Typography variant="caption" color="text.secondary">
                                    Available for trading
                                </Typography>
                            </CardContent>
                        </Card>
                    </Grid>

                    <Grid item xs={12} md={3}>
                        <Card>
                            <CardContent>
                                <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                                    <Remove color="error" sx={{ mr: 1 }} />
                                    <Typography variant="h6">Retired</Typography>
                                </Box>
                                <Typography variant="h4" fontWeight="bold" color="error.main">
                                    {carbonCredits?.usedCredits?.toFixed(2) || '0.00'}
                                </Typography>
                                <Typography variant="caption" color="text.secondary">
                                    Retired credits
                                </Typography>
                            </CardContent>
                        </Card>
                    </Grid>

                    <Grid item xs={12} md={3}>
                        <Card>
                            <CardContent>
                                <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                                    <TrendingUp color="info" sx={{ mr: 1 }} />
                                    <Typography variant="h6">Market Price</Typography>
                                </Box>
                                <Typography variant="h4" fontWeight="bold" color="info.main">
                                    ${carbonCredits?.pricePerCredit?.toFixed(2) || '0.00'}
                                </Typography>
                                <Typography variant="caption" color="text.secondary">
                                    Per credit
                                </Typography>
                            </CardContent>
                        </Card>
                    </Grid>
                </Grid>

                {/* Actions */}
                <Box sx={{ mb: 4, display: 'flex', gap: 2 }}>
                    <Button
                        variant="contained"
                        color="primary"
                        startIcon={<Add />}
                        onClick={() => setBuyDialogOpen(true)}
                        disabled={loading}
                    >
                        Buy Credits
                    </Button>
                    <Button
                        variant="outlined"
                        color="primary"
                        startIcon={<Remove />}
                        onClick={() => setSellDialogOpen(true)}
                        disabled={loading || !carbonCredits?.availableCredits}
                    >
                        Sell Credits
                    </Button>
                </Box>

                {/* Tabs */}
                <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 3 }}>
                    <Tabs value={tabValue} onChange={(e, newValue) => setTabValue(newValue)}>
                        <Tab label="Market" icon={<ShoppingCart />} iconPosition="start" />
                        <Tab label="Price History" icon={<TrendingUp />} iconPosition="start" />
                        <Tab label="Trade History" icon={<History />} iconPosition="start" />
                    </Tabs>
                    <TabSectionNavLinks
                        tabLabels={[...CARBON_TRADING_TAB_LABELS]}
                        currentIndex={tabValue}
                        onNavigate={setTabValue}
                    />
                </Box>

                {/* Tab Panels */}
                {tabValue === 0 && (
                    <Card>
                        <CardContent>
                            <Typography variant="h6" gutterBottom>
                                Market Listings
                            </Typography>
                            {loading ? (
                                <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
                                    <CircularProgress />
                                </Box>
                            ) : (
                                <TableContainer>
                                    <Table>
                                        <TableHead>
                                            <TableRow>
                                                <TableCell>Seller</TableCell>
                                                <TableCell>Project</TableCell>
                                                <TableCell align="right">Credits</TableCell>
                                                <TableCell align="right">Price/Credit</TableCell>
                                                <TableCell align="right">Total Value</TableCell>
                                                <TableCell>Status</TableCell>
                                                <TableCell align="right">Action</TableCell>
                                            </TableRow>
                                        </TableHead>
                                        <TableBody>
                                            {marketListings.length === 0 ? (
                                                <TableRow>
                                                    <TableCell colSpan={7} align="center">
                                                        No market listings available
                                                    </TableCell>
                                                </TableRow>
                                            ) : (
                                                marketListings.map((listing) => (
                                                    <TableRow key={listing._id}>
                                                        <TableCell>{listing.seller}</TableCell>
                                                        <TableCell>{listing.name || 'Marketplace Listing'}</TableCell>
                                                        <TableCell align="right">{listing.credits.toFixed(2)}</TableCell>
                                                        <TableCell align="right">${listing.pricePerCredit.toFixed(2)}</TableCell>
                                                        <TableCell align="right">${(listing.totalValue || 0).toFixed(2)}</TableCell>
                                                        <TableCell>
                                                            <Chip
                                                                label={listing.status}
                                                                color={listing.status === 'active' ? 'success' : 'default'}
                                                                size="small"
                                                            />
                                                        </TableCell>
                                                        <TableCell align="right">
                                                            <Button
                                                                size="small"
                                                                variant="contained"
                                                                onClick={() => openBuyDialog(listing)}
                                                                disabled={listing.status !== 'active'}
                                                            >
                                                                Buy
                                                            </Button>
                                                        </TableCell>
                                                    </TableRow>
                                                ))
                                            )}
                                        </TableBody>
                                    </Table>
                                </TableContainer>
                            )}
                        </CardContent>
                    </Card>
                )}

                {tabValue === 1 && (
                    <Card>
                        <CardContent>
                            <Typography variant="h6" gutterBottom>
                                Price History
                            </Typography>
                            <Box sx={{ height: 400 }}>
                                <ResponsiveContainer width="100%" height="100%">
                                    <ComposedChart data={priceHistory} margin={{ top: 8, right: 16, left: 0, bottom: 8 }}>
                                        <defs>
                                            <linearGradient id="carbonPriceFill" x1="0" y1="0" x2="0" y2="1">
                                                <stop offset="0%" stopColor="#2563eb" stopOpacity={0.35} />
                                                <stop offset="100%" stopColor="#2563eb" stopOpacity={0.02} />
                                            </linearGradient>
                                        </defs>
                                        <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} vertical={false} />
                                        <XAxis dataKey="date" tick={tickStyle} interval="preserveStartEnd" />
                                        <YAxis tick={tickStyle} width={48} />
                                        <Tooltip {...tipProps} />
                                        <Legend {...rechartsLegendProps} />
                                        <Area
                                            type="monotone"
                                            dataKey="price"
                                            fill="url(#carbonPriceFill)"
                                            stroke="none"
                                            legendType="none"
                                            {...chartAnimationProps}
                                        />
                                        <Line
                                            type="monotone"
                                            dataKey="price"
                                            stroke="#1d4ed8"
                                            strokeWidth={2.5}
                                            dot={false}
                                            activeDot={{ r: 6, strokeWidth: 0 }}
                                            name="Price ($)"
                                            {...chartAnimationProps}
                                        />
                                    </ComposedChart>
                                </ResponsiveContainer>
                            </Box>
                        </CardContent>
                    </Card>
                )}

                {tabValue === 2 && (
                    <Card>
                        <CardContent>
                            <Typography variant="h6" gutterBottom>
                                Trade History
                            </Typography>
                            <TableContainer>
                                <Table>
                                    <TableHead>
                                        <TableRow>
                                            <TableCell>Date</TableCell>
                                            <TableCell>Type</TableCell>
                                            <TableCell align="right">Credits</TableCell>
                                            <TableCell align="right">Price/Credit</TableCell>
                                            <TableCell align="right">Total Amount</TableCell>
                                            <TableCell>Status</TableCell>
                                        </TableRow>
                                    </TableHead>
                                    <TableBody>
                                        {tradeHistory.length === 0 ? (
                                            <TableRow>
                                                <TableCell colSpan={6} align="center">
                                                    No trade history available
                                                </TableCell>
                                            </TableRow>
                                        ) : (
                                            tradeHistory.map((trade) => (
                                                <TableRow key={trade._id}>
                                                    <TableCell>
                                                        {new Date(trade.createdAt).toLocaleDateString()}
                                                    </TableCell>
                                                    <TableCell>
                                                        <Chip
                                                                label={trade.type.toUpperCase()}
                                                                color={trade.type === 'purchase' ? 'primary' : 'secondary'}
                                                            size="small"
                                                        />
                                                    </TableCell>
                                                    <TableCell align="right">{trade.credits.toFixed(2)}</TableCell>
                                                    <TableCell align="right">${trade.pricePerCredit.toFixed(2)}</TableCell>
                                                    <TableCell align="right">${trade.totalAmount.toFixed(2)}</TableCell>
                                                    <TableCell>
                                                        <Chip
                                                            label={trade.status}
                                                            color={trade.status === 'completed' ? 'success' : 'default'}
                                                            size="small"
                                                        />
                                                    </TableCell>
                                                </TableRow>
                                            ))
                                        )}
                                    </TableBody>
                                </Table>
                            </TableContainer>
                        </CardContent>
                    </Card>
                )}
            </Box>

            {/* Buy Dialog */}
            <Dialog open={buyDialogOpen} onClose={() => setBuyDialogOpen(false)} maxWidth="sm" fullWidth>
                <DialogTitle>Buy Carbon Credits</DialogTitle>
                <DialogContent>
                    {selectedListing && (
                        <Box sx={{ pt: 2 }}>
                            <Typography variant="body2" gutterBottom>
                                Available Credits: <strong>{selectedListing.credits.toFixed(2)}</strong>
                            </Typography>
                            <Typography variant="body2" gutterBottom>
                                Price per Credit: <strong>${selectedListing.pricePerCredit.toFixed(2)}</strong>
                            </Typography>
                            <TextField
                                fullWidth
                                label="Number of Credits"
                                type="number"
                                value={buyAmount}
                                onChange={(e) => setBuyAmount(e.target.value)}
                                margin="normal"
                                inputProps={{ min: 0, max: selectedListing.credits, step: 0.01 }}
                            />
                            {buyAmount && (
                                <Typography variant="h6" sx={{ mt: 2 }}>
                                    Total: ${(parseFloat(buyAmount) * selectedListing.pricePerCredit).toFixed(2)}
                                </Typography>
                            )}
                        </Box>
                    )}
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setBuyDialogOpen(false)}>Cancel</Button>
                    <Button
                        onClick={handleBuyCredits}
                        variant="contained"
                        disabled={!buyAmount || loading}
                    >
                        {loading ? <CircularProgress size={24} /> : 'Buy'}
                    </Button>
                </DialogActions>
            </Dialog>

            {/* Sell Dialog */}
            <Dialog open={sellDialogOpen} onClose={() => setSellDialogOpen(false)} maxWidth="sm" fullWidth>
                <DialogTitle>Retire Carbon Credits</DialogTitle>
                <DialogContent>
                    <Box sx={{ pt: 2 }}>
                        <Typography variant="body2" gutterBottom>
                            Available Credits: <strong>{carbonCredits?.availableCredits?.toFixed(2) || '0.00'}</strong>
                        </Typography>
                        <TextField
                            fullWidth
                            label="Number of Credits"
                            type="number"
                            value={sellAmount}
                            onChange={(e) => setSellAmount(e.target.value)}
                            margin="normal"
                            inputProps={{ min: 0, max: carbonCredits?.availableCredits, step: 0.01 }}
                        />
                        <TextField
                            fullWidth
                            label="Reference Price per Credit"
                            type="number"
                            value={sellPrice}
                            onChange={(e) => setSellPrice(e.target.value)}
                            margin="normal"
                            InputProps={{
                                startAdornment: <InputAdornment position="start">$</InputAdornment>,
                            }}
                            inputProps={{ min: 0, step: 0.01 }}
                        />
                        {sellAmount && sellPrice && (
                            <Typography variant="h6" sx={{ mt: 2 }}>
                                Reference Value: ${(parseFloat(sellAmount) * parseFloat(sellPrice)).toFixed(2)}
                            </Typography>
                        )}
                    </Box>
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setSellDialogOpen(false)}>Cancel</Button>
                    <Button
                        onClick={handleSellCredits}
                        variant="contained"
                        disabled={!sellAmount || !sellPrice || loading}
                    >
                        {loading ? <CircularProgress size={24} /> : 'Retire Credits'}
                    </Button>
                </DialogActions>
            </Dialog>
        </Container>
    );
};

export default CarbonTrading;
