import React, { useCallback, useEffect, useRef, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardActions,
  CardContent,
  Chip,
  CircularProgress,
  Grid,
  Stack,
  Typography,
} from '@mui/material';
import {
  CloudSync as SyncIcon,
  UploadFile as UploadIcon,
} from '@mui/icons-material';
import ApiService from '../services/api';

export interface AccountingConnector {
  id: string;
  name: string;
  vendor: string;
  description: string;
  supportsImport: boolean;
  supportsApiSync: boolean;
}

interface ConnectorApiStatus {
  configured?: boolean;
  enabled?: boolean;
}

interface ImportSummary {
  imported: number;
  duplicates: number;
  invalid: number;
  persistFailures: number;
}

const parseTransactionsFromFile = async (file: File): Promise<unknown[]> => {
  const text = await file.text();
  const trimmed = text.trim();

  if (!trimmed) {
    throw new Error('The selected file is empty.');
  }

  if (file.name.toLowerCase().endsWith('.json') || trimmed.startsWith('[') || trimmed.startsWith('{')) {
    const parsed = JSON.parse(trimmed) as unknown;
    if (Array.isArray(parsed)) {
      return parsed;
    }
    if (
      parsed &&
      typeof parsed === 'object' &&
      'transactions' in parsed &&
      Array.isArray((parsed as { transactions: unknown[] }).transactions)
    ) {
      return (parsed as { transactions: unknown[] }).transactions;
    }
    throw new Error('JSON must be an array of transactions or an object with a transactions array.');
  }

  const lines = trimmed.split(/\r?\n/).filter((line) => line.trim().length > 0);
  if (lines.length < 2) {
    throw new Error('CSV must include a header row and at least one data row.');
  }

  const headers = lines[0].split(',').map((header) => header.trim());
  return lines.slice(1).map((line) => {
    const values = line.split(',').map((value) => value.trim());
    return headers.reduce<Record<string, string>>((row, header, index) => {
      row[header] = values[index] ?? '';
      return row;
    }, {});
  });
};

const AccountingConnectorsPanel: React.FC = () => {
  const fileInputRefs = useRef<Record<string, HTMLInputElement | null>>({});
  const [connectors, setConnectors] = useState<AccountingConnector[]>([]);
  const [apiStatusById, setApiStatusById] = useState<Record<string, ConnectorApiStatus>>({});
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [actionError, setActionError] = useState<string | null>(null);
  const [actionSuccess, setActionSuccess] = useState<string | null>(null);
  const [busyProviderId, setBusyProviderId] = useState<string | null>(null);

  const loadConnectors = useCallback(async () => {
    setLoading(true);
    setLoadError(null);

    try {
      const response = await ApiService.getAccountingConnectors();
      const connectorList = (response?.data?.connectors ?? []) as AccountingConnector[];
      setConnectors(connectorList);

      const apiConnectors = connectorList.filter((connector) => connector.supportsApiSync);
      const statusEntries = await Promise.all(
        apiConnectors.map(async (connector) => {
          try {
            const statusResponse = await ApiService.getAccountingConnectorStatus(connector.id);
            const api = statusResponse?.data?.api as ConnectorApiStatus | undefined;
            return [connector.id, api ?? {}] as const;
          } catch {
            return [connector.id, {}] as const;
          }
        })
      );

      setApiStatusById(Object.fromEntries(statusEntries));
    } catch (error) {
      setLoadError(error instanceof Error ? error.message : 'Unable to load accounting connectors.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadConnectors();
  }, [loadConnectors]);

  const summarizeImport = (summary?: ImportSummary) => {
    if (!summary) return 'Import completed.';
    return `Imported ${summary.imported} transaction(s). Skipped ${summary.duplicates} duplicate(s), ${summary.invalid} invalid row(s), ${summary.persistFailures} persist failure(s).`;
  };

  const handleImportFile = async (providerId: string, file: File) => {
    setBusyProviderId(providerId);
    setActionError(null);
    setActionSuccess(null);

    try {
      const transactions = await parseTransactionsFromFile(file);
      if (transactions.length === 0) {
        throw new Error('No transactions were found in the selected file.');
      }

      const response = await ApiService.importAccountingTransactions({
        provider: providerId,
        transactions,
      });

      if (response?.success === false) {
        throw new Error(response?.message || 'Import failed.');
      }

      setActionSuccess(summarizeImport(response?.data?.totals as ImportSummary | undefined));
    } catch (error) {
      setActionError(error instanceof Error ? error.message : 'Import failed.');
    } finally {
      setBusyProviderId(null);
    }
  };

  const handleSync = async (providerId: string) => {
    setBusyProviderId(providerId);
    setActionError(null);
    setActionSuccess(null);

    try {
      const response = await ApiService.syncAccountingTransactions(providerId);
      if (response?.success === false) {
        throw new Error(response?.message || 'Sync failed.');
      }

      setActionSuccess(summarizeImport(response?.data?.totals as ImportSummary | undefined));
      await loadConnectors();
    } catch (error) {
      setActionError(error instanceof Error ? error.message : 'Sync failed.');
    } finally {
      setBusyProviderId(null);
    }
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
        <CircularProgress size={32} />
      </Box>
    );
  }

  if (loadError) {
    return (
      <Alert severity="error" action={(
        <Button color="inherit" size="small" onClick={loadConnectors}>
          Retry
        </Button>
      )}
      >
        {loadError}
      </Alert>
    );
  }

  return (
    <Box>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        Connect Tally, Zoho Books, Busy, Marg, Vyapar, myBillBook, Khatabook, QuickBooks, Odoo, Clear,
        ProfitBooks, and HostBooks. Upload a JSON or CSV export, or use live sync where API credentials are configured.
      </Typography>

      {actionSuccess && (
        <Alert severity="success" sx={{ mb: 2 }} onClose={() => setActionSuccess(null)}>
          {actionSuccess}
        </Alert>
      )}

      {actionError && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setActionError(null)}>
          {actionError}
        </Alert>
      )}

      <Grid container spacing={2}>
        {connectors.map((connector) => {
          const apiStatus = apiStatusById[connector.id];
          const apiReady = Boolean(apiStatus?.configured);
          const isBusy = busyProviderId === connector.id;

          return (
            <Grid item xs={12} sm={6} lg={4} key={connector.id}>
              <Card variant="outlined" sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
                <CardContent sx={{ flexGrow: 1 }}>
                  <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 1 }}>
                    <Typography variant="subtitle1" sx={{ fontWeight: 600 }}>
                      {connector.name}
                    </Typography>
                  </Stack>
                  <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>
                    {connector.vendor}
                  </Typography>
                  <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
                    {connector.description}
                  </Typography>
                  <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
                    {connector.supportsImport && (
                      <Chip size="small" label="File import" variant="outlined" />
                    )}
                    {connector.supportsApiSync && (
                      <Chip
                        size="small"
                        label={apiReady ? 'API ready' : 'API not configured'}
                        color={apiReady ? 'success' : 'default'}
                        variant={apiReady ? 'filled' : 'outlined'}
                      />
                    )}
                  </Stack>
                </CardContent>
                <CardActions sx={{ px: 2, pb: 2, pt: 0 }}>
                  <input
                    ref={(element) => {
                      fileInputRefs.current[connector.id] = element;
                    }}
                    type="file"
                    accept=".json,.csv,application/json,text/csv"
                    hidden
                    onChange={(event) => {
                      const file = event.target.files?.[0];
                      event.target.value = '';
                      if (file) {
                        void handleImportFile(connector.id, file);
                      }
                    }}
                  />
                  <Button
                    size="small"
                    variant="outlined"
                    startIcon={isBusy ? <CircularProgress size={14} /> : <UploadIcon />}
                    disabled={!connector.supportsImport || isBusy}
                    onClick={() => fileInputRefs.current[connector.id]?.click()}
                  >
                    Import file
                  </Button>
                  {connector.supportsApiSync && (
                    <Button
                      size="small"
                      variant="contained"
                      startIcon={isBusy ? <CircularProgress size={14} color="inherit" /> : <SyncIcon />}
                      disabled={!apiReady || isBusy}
                      onClick={() => void handleSync(connector.id)}
                    >
                      Sync now
                    </Button>
                  )}
                </CardActions>
              </Card>
            </Grid>
          );
        })}
      </Grid>
    </Box>
  );
};

export default AccountingConnectorsPanel;
