import React, { useEffect } from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Grid,
  Paper,
  Stack,
  Typography,
} from '@mui/material';
import {
  AccountBalance as FinanceIcon,
  ArrowForward as ArrowForwardIcon,
  Nature as EcoIcon,
  Factory as FactoryIcon,
  Business as BusinessIcon,
  Insights as InsightsIcon,
  PersonAdd as RegisterIcon,
  Public as ClimateIcon,
  Savings as SavingsIcon,
  TrackChanges as MeasureIcon,
  PriceCheck as PricingIcon,
} from '@mui/icons-material';
import { Link as RouterLink, useNavigate } from 'react-router-dom';
import { alpha, useTheme } from '@mui/material/styles';
import { useRegistration } from '../context/RegistrationContext';
import BrandLogoMark from './BrandLogoMark';
import {
  CARBON_INTELLIGENCE_OVERVIEW,
  CLIMATE_AND_SAVINGS_HIGHLIGHTS,
  INDIA_SPECIFIC_INFO,
  PLATFORM_BENEFITS,
  POST_LOGIN_WORKFLOW,
  PRE_LOGIN_HERO,
  PRICING_TEASER_SECTION,
  WHY_MEASUREMENT_MATTERS,
} from '../constants/preLoginDashboardContent';
const SECTION_ICONS = {
  why: MeasureIcon,
  climate: ClimateIcon,
  benefits: InsightsIcon,
  india: FactoryIcon,
} as const;

interface HighlightSectionProps {
  id: string;
  title: string;
  intro: string;
  items: { title: string; description: string }[];
  icon: React.ElementType;
}

const HighlightSection: React.FC<HighlightSectionProps> = ({
  id,
  title,
  intro,
  items,
  icon: SectionIcon,
}) => {
  const theme = useTheme();

  return (
    <Box id={id} component="section" sx={{ mb: { xs: 4, md: 5 } }}>
      <Stack direction="row" spacing={1.5} alignItems="center" sx={{ mb: 2 }}>
        <Box
          sx={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            width: 40,
            height: 40,
            borderRadius: 2,
            bgcolor: alpha(theme.palette.primary.main, 0.12),
            color: 'primary.main',
          }}
        >
          <SectionIcon />
        </Box>
        <Typography variant="h5" component="h2" sx={{ fontWeight: 700 }}>
          {title}
        </Typography>
      </Stack>
      <Typography variant="body1" color="text.secondary" sx={{ mb: 3, maxWidth: 900 }}>
        {intro}
      </Typography>
      <Grid container spacing={2}>
        {items.map((item) => (
          <Grid item xs={12} sm={6} key={item.title}>
            <Card
              variant="outlined"
              sx={{
                height: '100%',
                borderColor: alpha(theme.palette.primary.main, 0.2),
                transition: 'border-color 0.2s, box-shadow 0.2s',
                '&:hover': {
                  borderColor: alpha(theme.palette.primary.main, 0.45),
                  boxShadow: theme.shadows[2],
                },
              }}
            >
              <CardContent>
                <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 1 }}>
                  {item.title}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  {item.description}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>
    </Box>
  );
};

const PreLoginDashboard: React.FC = () => {
  const theme = useTheme();
  const navigate = useNavigate();
  const { isRegistered } = useRegistration();
  const isDark = theme.palette.mode === 'dark';

  useEffect(() => {
    if (isRegistered) {
      navigate('/dashboard', { replace: true });
    }
  }, [isRegistered, navigate]);

  if (isRegistered) {
    return null;
  }

  return (
    <Box sx={{ pb: 4 }}>
      <Paper
        elevation={0}
        sx={{
          p: { xs: 3, md: 4 },
          mb: 4,
          borderRadius: 3,
          border: `1px solid ${alpha(theme.palette.primary.main, isDark ? 0.28 : 0.18)}`,
          background: isDark
            ? `linear-gradient(145deg, ${alpha(theme.palette.primary.dark, 0.22)} 0%, ${alpha(theme.palette.background.paper, 0.6)} 100%)`
            : 'linear-gradient(135deg, rgba(76, 175, 80, 0.08) 0%, rgba(46, 125, 50, 0.12) 100%)',
        }}
      >
        <Grid container spacing={3} alignItems="center">
          <Grid item xs={12} md={7}>
            <Chip
              label="Choose MSME or enterprise carbon emissions pathway"
              size="small"
              color="primary"
              variant="outlined"
              sx={{ mb: 2 }}
            />
            <Typography
              variant="h3"
              component="h1"
              gutterBottom
              sx={{
                fontWeight: 800,
                fontSize: { xs: '1.75rem', md: '2.25rem' },
                background: 'linear-gradient(135deg, #4caf50 0%, #2e7d32 100%)',
                backgroundClip: 'text',
                WebkitBackgroundClip: 'text',
                WebkitTextFillColor: 'transparent',
              }}
            >
              {PRE_LOGIN_HERO.title}
            </Typography>
            <Typography variant="h6" color="text.secondary" sx={{ mb: 3, fontWeight: 400, lineHeight: 1.6 }}>
              {PRE_LOGIN_HERO.subtitle}
            </Typography>
            <Typography variant="body1" color="text.secondary" sx={{ mb: 3, maxWidth: 720 }}>
              {CARBON_INTELLIGENCE_OVERVIEW}
            </Typography>
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} flexWrap="wrap" useFlexGap>
              <Button
                component={RouterLink}
                to="/login?type=msme"
                variant="contained"
                size="large"
                startIcon={<FactoryIcon />}
                sx={{
                  py: 1.25,
                  background: 'linear-gradient(135deg, #4caf50 0%, #2e7d32 100%)',
                  '&:hover': {
                    background: 'linear-gradient(135deg, #43a047 0%, #1b5e20 100%)',
                  },
                }}
              >
                MSME carbon emissions
              </Button>
              <Button
                component={RouterLink}
                to="/login?type=enterprise"
                variant="contained"
                size="large"
                startIcon={<BusinessIcon />}
                color="secondary"
                sx={{ py: 1.25 }}
              >
                Enterprise / corporation emissions
              </Button>
              <Button
                component={RouterLink}
                to="/register?type=msme"
                variant="outlined"
                size="large"
                startIcon={<RegisterIcon />}
                color="primary"
              >
                Register MSME
              </Button>
              <Button
                component={RouterLink}
                to="/pricing"
                variant="text"
                size="large"
                startIcon={<PricingIcon />}
                color="primary"
              >
                View pricing
              </Button>
            </Stack>
          </Grid>
          <Grid item xs={12} md={5} sx={{ textAlign: 'center' }}>
            <BrandLogoMark width={280} sx={{ maxWidth: '100%', mx: 'auto' }} />
            <Stack
              direction="row"
              spacing={1}
              justifyContent="center"
              flexWrap="wrap"
              useFlexGap
              sx={{ mt: 2 }}
            >
              <Chip icon={<EcoIcon />} label="GHG scopes 1–3" size="small" variant="outlined" />
              <Chip icon={<SavingsIcon />} label="Carbon savings" size="small" variant="outlined" />
              <Chip icon={<FinanceIcon />} label="Green finance ready" size="small" variant="outlined" />
            </Stack>
          </Grid>
        </Grid>
      </Paper>

      <HighlightSection
        id="why-measure"
        title="Why carbon measurement matters"
        intro="For MSMEs, emissions measurement is no longer optional background work—it is operational intelligence that connects climate, cost, and compliance."
        items={WHY_MEASUREMENT_MATTERS}
        icon={SECTION_ICONS.why}
      />

      <HighlightSection
        id="climate-savings"
        title="Climate impact & carbon savings"
        intro="Carbon Intelligence helps you see how operations contribute to climate impact today—and where measurable savings are achievable tomorrow."
        items={CLIMATE_AND_SAVINGS_HIGHLIGHTS}
        icon={SECTION_ICONS.climate}
      />

      <Box component="section" id="pricing" sx={{ mb: { xs: 4, md: 5 } }}>
        <Stack direction="row" spacing={1.5} alignItems="center" sx={{ mb: 2 }}>
          <Box
            sx={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              width: 40,
              height: 40,
              borderRadius: 2,
              bgcolor: alpha(theme.palette.primary.main, 0.12),
              color: 'primary.main',
            }}
          >
            <PricingIcon />
          </Box>
          <Typography variant="h5" component="h2" sx={{ fontWeight: 700 }}>
            {PRICING_TEASER_SECTION.title}
          </Typography>
        </Stack>
        <Typography variant="body1" color="text.secondary" sx={{ mb: 2.5, maxWidth: 900 }}>
          {PRICING_TEASER_SECTION.description}
        </Typography>
        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
          <Button
            component={RouterLink}
            to="/pricing"
            variant="contained"
            startIcon={<PricingIcon />}
            sx={{
              background: 'linear-gradient(135deg, #4caf50 0%, #2e7d32 100%)',
              '&:hover': {
                background: 'linear-gradient(135deg, #43a047 0%, #1b5e20 100%)',
              },
            }}
          >
            {PRICING_TEASER_SECTION.ctaPricing}
          </Button>
          <Button
            component={RouterLink}
            to="/register?type=msme"
            variant="outlined"
            startIcon={<RegisterIcon />}
          >
            {PRICING_TEASER_SECTION.ctaRegister}
          </Button>
        </Stack>
      </Box>

      <HighlightSection
        id="benefits"
        title="Platform benefits after sign-in"
        intro="Once you log in and complete onboarding, the full workspace unlocks for continuous emissions measurement and reporting."
        items={PLATFORM_BENEFITS}
        icon={SECTION_ICONS.benefits}
      />

      <HighlightSection
        id="india"
        title="India-specific context"
        intro="The platform is aligned with domestic disclosure, energy-intensity, and emerging carbon-market programmes relevant to Indian MSME suppliers and exporters."
        items={INDIA_SPECIFIC_INFO}
        icon={SECTION_ICONS.india}
      />

      <Box component="section" id="workflow" sx={{ mb: 4 }}>
        <Typography variant="h5" component="h2" sx={{ fontWeight: 700, mb: 2 }}>
          Your workflow after login
        </Typography>
        <Typography variant="body1" color="text.secondary" sx={{ mb: 3, maxWidth: 900 }}>
          Sign in to move from this overview into hands-on carbon emissions measurement, dashboard analytics, and reporting cycles.
        </Typography>
        <Grid container spacing={2}>
          {POST_LOGIN_WORKFLOW.map((step) => (
            <Grid item xs={12} sm={6} md={3} key={step.step}>
              <Paper
                sx={{
                  p: 2.5,
                  height: '100%',
                  border: `1px solid ${alpha(theme.palette.divider, 0.8)}`,
                }}
              >
                <Typography
                  variant="overline"
                  color="primary"
                  sx={{ fontWeight: 800, letterSpacing: 1 }}
                >
                  Step {step.step}
                </Typography>
                <Typography variant="subtitle1" sx={{ fontWeight: 700, mt: 0.5, mb: 1 }}>
                  {step.title}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  {step.description}
                </Typography>
              </Paper>
            </Grid>
          ))}
        </Grid>
      </Box>

      <Paper
        elevation={0}
        sx={{
          p: { xs: 3, md: 4 },
          textAlign: 'center',
          borderRadius: 3,
          border: `1px solid ${alpha(theme.palette.primary.main, isDark ? 0.28 : 0.18)}`,
          bgcolor: alpha(theme.palette.primary.main, isDark ? 0.08 : 0.04),
        }}
      >
        <Typography variant="h6" sx={{ fontWeight: 700, mb: 1 }}>
          Ready to start measuring?
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2.5, maxWidth: 560, mx: 'auto' }}>
          Create an account or sign in to access your Operational Control Center, carbon assessment,
          compliance hub, and reporting tools.
        </Typography>
        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} justifyContent="center">
          <Button
            component={RouterLink}
            to="/login?type=msme"
            variant="contained"
            size="large"
            endIcon={<ArrowForwardIcon />}
            sx={{
              background: 'linear-gradient(135deg, #4caf50 0%, #2e7d32 100%)',
              '&:hover': {
                background: 'linear-gradient(135deg, #43a047 0%, #1b5e20 100%)',
              },
            }}
          >
            MSME sign in
          </Button>
          <Button
            component={RouterLink}
            to="/login?type=enterprise"
            variant="outlined"
            size="large"
            endIcon={<ArrowForwardIcon />}
          >
            Enterprise sign in
          </Button>
        </Stack>
      </Paper>
    </Box>
  );
};

export default PreLoginDashboard;
