import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  Grid,
  LinearProgress,
  Slider,
  Stack,
  Tab,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Tabs,
  Typography,
  Paper,
} from '@mui/material';
import { useTheme } from '@mui/material/styles';
import { useUrlTabParam } from '../hooks/useUrlTabParam';
import {
  AutoAwesome as AutoAwesomeIcon,
  Refresh as RefreshIcon,
  TrendingDown as TrendingDownIcon,
} from '@mui/icons-material';
import {
  BarChart,
  CartesianGrid,
  ComposedChart,
  Bar,
  Line,
  Legend,
  ResponsiveContainer,
  ReferenceLine,
  Tooltip as RechartsTooltip,
  XAxis,
  YAxis,
} from 'recharts';
import {
  axisTickForMode,
  cartesianGridStroke,
  chartAnimationPropsFor,
  rechartsLegendProps,
  rechartsTooltipProps,
} from '../theme/rechartsAppearances';
import {
  CO2E_METHODOLOGY_SUBTITLE,
  GHG_SCOPE_HEX,
  formatAxisTickKg,
  yAxisLabelForKgDomain,
} from '../constants/carbonVisualization';
import { usePrefersReducedMotion } from '../hooks/usePrefersReducedMotion';
import ApiService from '../services/api';

const REDUCTION_PCT_STORAGE_KEY = 'sustainow_emissions_reduction_target_pct_v1';

const toSafeNumber = (value: unknown): number => {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
};

interface TxLike {
  date?: string;
  carbonFootprint?: { co2Emissions?: number };
}

const monthBucketFromDate = (dateValue?: string): string | null => {
  if (!dateValue) return null;
  const d = new Date(dateValue);
  if (Number.isNaN(d.getTime())) return null;
  const m = String(d.getMonth() + 1).padStart(2, '0');
  return `${d.getFullYear()}-${m}`;
};

const formatMonthLabel = (bucket: string) => {
  const [y, m] = bucket.split('-');
  if (!y || !m) return bucket;
  const parsed = new Date(Number(y), Number(m) - 1, 1);
  if (Number.isNaN(parsed.getTime())) return bucket;
  return new Intl.DateTimeFormat('en-IN', { month: 'short', year: 'numeric' }).format(parsed);
};

const parseApiPeriodRows = (raw: unknown): { key: string; kg: number }[] => {
  if (!raw) return [];
  if (Array.isArray(raw)) {
    return raw
      .filter(Boolean)
      .map((row: Record<string, unknown>) => {
        const key = String(row.periodStart ?? row.period ?? row.startDate ?? row.bucket ?? '');
        const kg = toSafeNumber(row.totalEmissions ?? row.totalCO2Emissions);
        return { key, kg };
      })
      .filter((r) => /^(\d{4})-(\d{2})$/.test(r.key));
  }
  const summary = raw as Record<string, unknown>;
  const groups = summary.groups;
  if (Array.isArray(groups)) {
    return groups
      .map((g: Record<string, unknown>) => ({
        key: String(g.periodStart ?? g.startDate ?? g.bucket ?? g.period ?? ''),
        kg: toSafeNumber(g.totalEmissions ?? g.totalCO2Emissions),
      }))
      .filter((r) => /^(\d{4})-(\d{2})$/.test(r.key));
  }
  const nested =
    (summary as { periodWise?: { monthly?: Record<string, unknown>[] } }).periodWise?.monthly ||
    (summary as { mobileBreakdown?: { periodWise?: { monthly?: Record<string, unknown>[] } } }).mobileBreakdown
      ?.periodWise?.monthly;
  if (Array.isArray(nested)) {
    return nested
      .map((g: Record<string, unknown>) => ({
        key: String(g.period ?? ''),
        kg: toSafeNumber(g.totalCO2Emissions ?? g.totalEmissions),
      }))
      .filter((r) => /^(\d{4})-(\d{2})$/.test(r.key));
  }
  return [];
};

const aggregateTransactionsByMonth = (transactions: TxLike[]): Map<string, number> => {
  const map = new Map<string, number>();
  transactions.forEach((t) => {
    const key = monthBucketFromDate(t.date);
    if (!key) return;
    const kg = toSafeNumber(t.carbonFootprint?.co2Emissions);
    map.set(key, (map.get(key) || 0) + kg);
  });
  return map;
};

const mergeMonthlyKg = (apiRows: { key: string; kg: number }[], txnMap: Map<string, number>): { key: string; kg: number }[] => {
  const merged = new Map<string, number>();
  apiRows.forEach(({ key, kg }) => {
    merged.set(key, Math.max(merged.get(key) || 0, kg));
  });
  txnMap.forEach((kg, key) => {
    if (!merged.has(key)) merged.set(key, kg);
  });
  return Array.from(merged.entries())
    .map(([key, kg]) => ({ key, kg }))
    .sort((a, b) => a.key.localeCompare(b.key));
};

type AiCapability = { id: string; title: string; status?: string; summary?: string; capability?: string };
type AiRec = { id: string; title: string; description?: string; priority?: string; potentialCO2Reduction?: number | null };

interface AiAnalyticsPayload {
  engine?: { name?: string; version?: string; readinessScore?: number; activeAgents?: number; totalAgents?: number };
  capabilities?: AiCapability[];
  synthesis?: Record<string, unknown>;
  benchmarks?: {
    industryAverageKg?: number;
    bestInClassKg?: number;
    previousAssessmentKg?: number;
  };
  charts?: {
    recommendations?: AiRec[];
    scopeMonthlyStack?: Array<{
      period: string;
      label: string;
      scope1: number;
      scope2: number;
      scope3: number;
      total: number;
    }>;
  };
  compliance?: { summary?: string; readinessPercent?: number };
}

async function loadAllTransactions(): Promise<TxLike[]> {
  const all: TxLike[] = [];
  for (let page = 1; page <= 40; page += 1) {
    const response = await ApiService.getTransactions({ page, limit: 100 });
    const list =
      (response as { data?: { transactions?: TxLike[] } })?.data?.transactions ||
      (response as { transactions?: TxLike[] })?.transactions ||
      (response as { data?: TxLike[] })?.data ||
      [];
    if (!Array.isArray(list) || list.length === 0) break;
    all.push(...list);
    if (list.length < 100) break;
  }
  return all;
}

const quarterKey = (bucket: string) => {
  const [y, m] = bucket.split('-').map(Number);
  if (!y || !m) return bucket;
  const q = Math.floor((m - 1) / 3) + 1;
  return `${y}-Q${q}`;
};

const halfYearKey = (bucket: string) => {
  const [y, m] = bucket.split('-').map(Number);
  if (!y || !m) return bucket;
  return `${y}-H${m <= 6 ? 1 : 2}`;
};

const yearKey = (bucket: string) => bucket.slice(0, 4);

const EmissionsReductionTargets: React.FC = () => {
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';
  const gridStroke = cartesianGridStroke(isDark);
  const tickStyle = axisTickForMode(isDark);
  const tipProps = rechartsTooltipProps(isDark);
  const prefersReducedMotion = usePrefersReducedMotion();
  const chartMotion = chartAnimationPropsFor(prefersReducedMotion);

  const [innerTab, setInnerTab] = useUrlTabParam(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [monthlySeries, setMonthlySeries] = useState<{ key: string; kg: number }[]>([]);
  const [reductionPct, setReductionPct] = useState(() => {
    const stored = Number(localStorage.getItem(REDUCTION_PCT_STORAGE_KEY));
    if (Number.isFinite(stored) && stored >= 0 && stored <= 40) return stored;
    return 10;
  });
  const [aiPayload, setAiPayload] = useState<AiAnalyticsPayload | null>(null);
  const [aiLoading, setAiLoading] = useState(false);
  const [aiError, setAiError] = useState<string | null>(null);

  const persistReduction = (value: number) => {
    const clamped = Math.min(40, Math.max(0, value));
    setReductionPct(clamped);
    localStorage.setItem(REDUCTION_PCT_STORAGE_KEY, String(clamped));
  };

  const refreshAi = useCallback(async (transactions: TxLike[]) => {
    setAiLoading(true);
    setAiError(null);
    try {
      const response = await ApiService.runCarbonAIAnalyticsEngine({
        transactions: transactions as unknown[],
      });
      const payload = (response as { data?: AiAnalyticsPayload })?.data ?? response;
      if (payload && typeof payload === 'object') {
        setAiPayload(payload as AiAnalyticsPayload);
      } else {
        setAiPayload(null);
      }
    } catch (e) {
      console.error('AI analytics for targets:', e);
      setAiPayload(null);
      setAiError('Recommendations could not be loaded. Targets and charts still use your recorded emissions.');
    } finally {
      setAiLoading(false);
    }
  }, []);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const [transactions, periodResponse] = await Promise.all([
        loadAllTransactions(),
        ApiService.getCarbonAssessmentByPeriod({ groupBy: 'monthly', limit: 36 }).catch(() => null),
      ]);
      const rawSummary =
        (periodResponse as { data?: { summary?: unknown } })?.data?.summary ??
        (periodResponse as { summary?: unknown })?.summary ??
        (periodResponse as { data?: unknown })?.data;
      const apiRows = parseApiPeriodRows(rawSummary);
      const txnMap = aggregateTransactionsByMonth(transactions);
      const merged = mergeMonthlyKg(apiRows, txnMap);
      setMonthlySeries(merged);
      void refreshAi(transactions);
    } catch (e) {
      console.error(e);
      setError('Unable to load emissions history for targets.');
      setMonthlySeries([]);
    } finally {
      setLoading(false);
    }
  }, [refreshAi]);

  useEffect(() => {
    void load();
  }, [load]);

  const targetModel = useMemo(() => {
    const series = monthlySeries.filter((m) => m.kg > 0);
    if (series.length === 0) {
      return {
        baselineMonthly: 0,
        annualTargetKg: 0,
        monthlyFlatTarget: 0,
        glideTargets: monthlySeries.map(() => 0),
      };
    }
    const tail = series.slice(-Math.min(3, series.length));
    const baselineMonthly = tail.reduce((s, x) => s + x.kg, 0) / tail.length;
    const annualTargetKg = baselineMonthly * 12 * (1 - reductionPct / 100);
    const monthlyFlatTarget = annualTargetKg / 12;
    const glideTargets = monthlySeries.map((_, idx) => {
      const t = monthlySeries.length > 1 ? idx / (monthlySeries.length - 1) : 0;
      return baselineMonthly * (1 - (reductionPct / 100) * t);
    });
    return { baselineMonthly, annualTargetKg, monthlyFlatTarget, glideTargets };
  }, [monthlySeries, reductionPct]);

  const chartRows = useMemo(() => {
    const slice = monthlySeries.slice(-24);
    return slice.map((row) => {
      const globalIdx = monthlySeries.findIndex((m) => m.key === row.key);
      const glide =
        globalIdx >= 0 && targetModel.glideTargets[globalIdx] != null
          ? targetModel.glideTargets[globalIdx]
          : targetModel.monthlyFlatTarget;
      const flat = targetModel.monthlyFlatTarget;
      return {
        key: row.key,
        label: formatMonthLabel(row.key),
        actualKg: Number(row.kg.toFixed(2)),
        targetKg: Number((flat > 0 ? flat : glide).toFixed(2)),
        glideTargetKg: Number(glide.toFixed(2)),
        variance: Number((row.kg - (flat > 0 ? flat : glide)).toFixed(2)),
      };
    });
  }, [monthlySeries, targetModel]);

  const quarterlyRows = useMemo(() => {
    const map = new Map<string, { actual: number; months: number }>();
    monthlySeries.forEach((m) => {
      const qk = quarterKey(m.key);
      const cur = map.get(qk) || { actual: 0, months: 0 };
      cur.actual += m.kg;
      cur.months += 1;
      map.set(qk, cur);
    });
    const quarterlyTarget = targetModel.annualTargetKg / 4;
    return Array.from(map.entries())
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([period, v]) => ({
        period,
        actual: v.actual,
        target: quarterlyTarget,
        progressPct: quarterlyTarget > 0 ? Math.min(150, (v.actual / quarterlyTarget) * 100) : 0,
        status: quarterlyTarget > 0 && v.actual <= quarterlyTarget ? 'Within target' : 'Above target',
      }));
  }, [monthlySeries, targetModel.annualTargetKg]);

  const halfYearRows = useMemo(() => {
    const map = new Map<string, number>();
    monthlySeries.forEach((m) => {
      const hk = halfYearKey(m.key);
      map.set(hk, (map.get(hk) || 0) + m.kg);
    });
    const halfTarget = targetModel.annualTargetKg / 2;
    return Array.from(map.entries())
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([period, actual]) => ({
        period,
        actual,
        target: halfTarget,
        progressPct: halfTarget > 0 ? Math.min(150, (actual / halfTarget) * 100) : 0,
        status: halfTarget > 0 && actual <= halfTarget ? 'Within target' : 'Above target',
      }));
  }, [monthlySeries, targetModel.annualTargetKg]);

  const annualRows = useMemo(() => {
    const map = new Map<string, number>();
    monthlySeries.forEach((m) => {
      const yk = yearKey(m.key);
      map.set(yk, (map.get(yk) || 0) + m.kg);
    });
    const annualT = targetModel.annualTargetKg;
    return Array.from(map.entries())
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([year, actual]) => ({
        year,
        actual,
        target: annualT,
        progressPct: annualT > 0 ? Math.min(150, (actual / annualT) * 100) : 0,
        status: annualT > 0 && actual <= annualT ? 'Within target' : 'Above target',
      }));
  }, [monthlySeries, targetModel.annualTargetKg]);

  const ytdSummary = useMemo(() => {
    const now = new Date();
    const y = now.getFullYear();
    const ytd = monthlySeries.filter((m) => m.key.startsWith(String(y))).reduce((s, m) => s + m.kg, 0);
    const monthsElapsed = Math.max(1, monthlySeries.filter((m) => m.key.startsWith(String(y))).length || now.getMonth() + 1);
    const ytdTarget = (targetModel.annualTargetKg / 12) * monthsElapsed;
    const score = ytdTarget > 0 ? Math.round(Math.min(100, (ytdTarget / Math.max(ytd, 0.001)) * 100)) : 0;
    return { ytd, ytdTarget, score, year: y };
  }, [monthlySeries, targetModel.annualTargetKg]);

  const recommendations = aiPayload?.charts?.recommendations ?? [];
  const scopeStackRows = useMemo(() => aiPayload?.charts?.scopeMonthlyStack ?? [], [aiPayload]);

  const chartYMax = useMemo(() => {
    let m = 1;
    chartRows.forEach((r) => {
      m = Math.max(m, r.actualKg, r.targetKg, r.glideTargetKg);
    });
    return m;
  }, [chartRows]);

  const industryAvgMonthly = useMemo(() => {
    const v = toSafeNumber(aiPayload?.benchmarks?.industryAverageKg);
    return v > 0 ? v / 12 : 0;
  }, [aiPayload]);

  const bestInClassMonthly = useMemo(() => {
    const v = toSafeNumber(aiPayload?.benchmarks?.bestInClassKg);
    return v > 0 ? v / 12 : 0;
  }, [aiPayload]);

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight={360} gap={2}>
        <CircularProgress />
        <Typography variant="body1">Loading emissions and targets…</Typography>
      </Box>
    );
  }

  return (
    <Box>
      <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 2 }}>
        <TrendingDownIcon color="primary" fontSize="large" />
        <Box>
          <Typography variant="h4" component="h1">
            Emissions reduction targets
          </Typography>
          <Typography variant="body2" color="text.secondary">
            Compare recorded kg CO₂e against glide and flat budgets. Benchmark bands use assessment industry and best-in-class
            totals (when stored) as a monthly proration for context. {CO2E_METHODOLOGY_SUBTITLE}
          </Typography>
        </Box>
      </Stack>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}

      <Card variant="outlined" sx={{ mb: 2 }}>
        <CardContent>
          <Typography variant="subtitle1" gutterBottom>
            Annual reduction ambition
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
            Targets scale from your recent monthly emissions baseline (trailing three active months). Adjust the slider to model
            {` `}
            {reductionPct}% lower annual emissions than that baseline.
          </Typography>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems={{ sm: 'center' }}>
            <Slider
              value={reductionPct}
              onChange={(_, v) => persistReduction(v as number)}
              min={0}
              max={40}
              step={1}
              valueLabelDisplay="auto"
              aria-label="Annual emissions reduction percent"
              sx={{ maxWidth: { sm: 360 }, flex: 1 }}
            />
            <Chip label={`${reductionPct}% YoY-style cut`} color="primary" variant="outlined" />
          </Stack>
          <Grid container spacing={2} sx={{ mt: 1 }}>
            <Grid item xs={12} sm={4}>
              <Typography variant="caption" color="text.secondary">
                Baseline (avg last 3 active months)
              </Typography>
              <Typography variant="h6">{targetModel.baselineMonthly.toFixed(1)} kg / month</Typography>
            </Grid>
            <Grid item xs={12} sm={4}>
              <Typography variant="caption" color="text.secondary">
                Modelled annual target
              </Typography>
              <Typography variant="h6">{targetModel.annualTargetKg.toFixed(0)} kg CO₂</Typography>
            </Grid>
            <Grid item xs={12} sm={4}>
              <Typography variant="caption" color="text.secondary">
                Flat monthly budget (target ÷ 12)
              </Typography>
              <Typography variant="h6">{targetModel.monthlyFlatTarget.toFixed(1)} kg / month</Typography>
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      <Tabs
        value={innerTab}
        onChange={(_event, value) => setInnerTab(value)}
        sx={{ borderBottom: 1, borderColor: 'divider', mb: 2 }}
      >
        <Tab label="Progress & charts" id="ert-tab-0" aria-controls="ert-panel-0" />
        <Tab label="Monthly · quarterly · half-year · annual" id="ert-tab-1" aria-controls="ert-panel-1" />
        <Tab label="Recommendations" id="ert-tab-2" aria-controls="ert-panel-2" />
      </Tabs>

      {innerTab === 0 && (
        <Stack spacing={2}>
          {aiPayload?.capabilities && aiPayload.capabilities.length > 0 && (
            <Card variant="outlined">
              <CardContent>
                <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 1 }}>
                  <AutoAwesomeIcon color="primary" fontSize="small" />
                  <Typography variant="subtitle1">Multi-agent analytics status</Typography>
                  {typeof aiPayload.engine?.readinessScore === 'number' && (
                    <Chip size="small" label={`Engine readiness ${aiPayload.engine.readinessScore}%`} variant="outlined" />
                  )}
                </Stack>
                <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>
                  Carbon analyzer, recommendation, anomaly, and trend agents power scope stacks and recommendations when active in
                  your workspace.
                </Typography>
                <Stack direction="row" flexWrap="wrap" gap={0.75}>
                  {aiPayload.capabilities.map((cap) => (
                    <Chip
                      key={cap.id}
                      size="small"
                      color={cap.status === 'active' ? 'success' : 'default'}
                      variant={cap.status === 'active' ? 'filled' : 'outlined'}
                      label={cap.title}
                    />
                  ))}
                </Stack>
              </CardContent>
            </Card>
          )}

          <Card variant="outlined">
            <CardContent>
              <Typography variant="h6" gutterBottom>
                {ytdSummary.year} progress vs prorated target
              </Typography>
              <Typography variant="body2" color="text.secondary" paragraph>
                Year-to-date actual emissions compared with the portion of the annual target elapsed for months with data in
                {` ${ytdSummary.year}.`}
              </Typography>
              <Stack spacing={1} sx={{ maxWidth: 480 }}>
                <Stack direction="row" justifyContent="space-between">
                  <Typography variant="body2">YTD actual</Typography>
                  <Typography variant="body2" fontWeight={600}>
                    {ytdSummary.ytd.toFixed(1)} kg
                  </Typography>
                </Stack>
                <Stack direction="row" justifyContent="space-between">
                  <Typography variant="body2">YTD target (prorated)</Typography>
                  <Typography variant="body2" fontWeight={600}>
                    {ytdSummary.ytdTarget.toFixed(1)} kg
                  </Typography>
                </Stack>
                <Typography variant="caption" color="text.secondary">
                  On-track score (100 = at or under prorated budget)
                </Typography>
                <LinearProgress
                  variant="determinate"
                  value={Math.min(100, ytdSummary.score)}
                  sx={{ height: 10, borderRadius: 1 }}
                  color={ytdSummary.score >= 95 ? 'success' : ytdSummary.score >= 80 ? 'warning' : 'error'}
                />
                <Typography variant="caption">{ytdSummary.score}%</Typography>
              </Stack>
            </CardContent>
          </Card>

          <Card variant="outlined">
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Actual vs target emissions over time
              </Typography>
              <Typography variant="body2" color="text.secondary" paragraph>
                Bars show recorded monthly kg CO₂e. The red line is the flat monthly budget; the dashed blue line is the glide
                path. Orange and purple reference lines (when visible) prorate industry average and best-in-class footprint totals
                from your latest stored assessment to a monthly equivalent for context only.
              </Typography>
              <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>
                {CO2E_METHODOLOGY_SUBTITLE}
              </Typography>
              {chartRows.length === 0 ? (
                <Alert severity="info">
                  No emissions for the selected history. Add dated transactions with carbon footprints or complete a periodic
                  assessment so this chart is not mistaken for zero emissions.
                </Alert>
              ) : (
                <Box
                  sx={{ width: '100%', height: 360 }}
                  role="img"
                  aria-label="Monthly actual emissions as bars with flat and glide target lines and optional benchmark references."
                >
                  <ResponsiveContainer>
                    <ComposedChart data={chartRows} margin={{ top: 8, right: 8, left: 0, bottom: 8 }}>
                      <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} vertical={false} />
                      <XAxis dataKey="label" tick={{ ...tickStyle }} interval="preserveStartEnd" />
                      <YAxis
                        tick={{ ...tickStyle }}
                        tickFormatter={(v: number) => formatAxisTickKg(v)}
                        label={{
                          value: yAxisLabelForKgDomain(chartYMax),
                          angle: -90,
                          position: 'insideLeft',
                          fill: tickStyle.fill,
                          fontSize: 11,
                        }}
                      />
                      <RechartsTooltip {...tipProps} formatter={(v: number) => `${formatAxisTickKg(v)} CO₂e`} />
                      <Legend {...rechartsLegendProps} />
                      {industryAvgMonthly > 0 && (
                        <ReferenceLine
                          y={industryAvgMonthly}
                          stroke="#ea580c"
                          strokeDasharray="4 4"
                          label={{ value: 'Industry (prorated)', fill: tickStyle.fill, fontSize: 10 }}
                        />
                      )}
                      {bestInClassMonthly > 0 && (
                        <ReferenceLine
                          y={bestInClassMonthly}
                          stroke="#7c3aed"
                          strokeDasharray="3 6"
                          label={{ value: 'Best in class (prorated)', fill: tickStyle.fill, fontSize: 10 }}
                        />
                      )}
                      <Bar dataKey="actualKg" name="Actual" fill="#059669" radius={[6, 6, 0, 0]} {...chartMotion} />
                      <Line
                        type="monotone"
                        dataKey="targetKg"
                        name="Flat monthly target"
                        stroke="#be123c"
                        strokeWidth={2.5}
                        dot={false}
                        activeDot={{ r: 5 }}
                        {...chartMotion}
                      />
                      <Line
                        type="monotone"
                        dataKey="glideTargetKg"
                        name="Glide target"
                        stroke="#2563eb"
                        strokeDasharray="6 4"
                        strokeWidth={2}
                        dot={false}
                        activeDot={{ r: 5 }}
                        {...chartMotion}
                      />
                    </ComposedChart>
                  </ResponsiveContainer>
                </Box>
              )}
            </CardContent>
          </Card>

          {scopeStackRows.length > 0 && (
            <Card variant="outlined">
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  Monthly emissions by scope (transactions)
                </Typography>
                <Typography variant="body2" color="text.secondary" paragraph>
                  Stacked bars attribute kg CO₂e to scopes where transaction footprints include an emission breakdown. Built from
                  the multi-agent analytics engine over your recent transaction set.
                </Typography>
                <Box
                  sx={{ width: '100%', height: 320 }}
                  role="img"
                  aria-label="Stacked bar chart of scope one two and three emissions by month from transaction data."
                >
                  <ResponsiveContainer>
                    <BarChart data={scopeStackRows} margin={{ top: 8, right: 8, left: 0, bottom: 8 }}>
                      <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} vertical={false} />
                      <XAxis dataKey="label" tick={{ ...tickStyle }} interval="preserveStartEnd" />
                      <YAxis
                        tick={{ ...tickStyle }}
                        tickFormatter={(v: number) => formatAxisTickKg(v)}
                        label={{
                          value: yAxisLabelForKgDomain(Math.max(...scopeStackRows.map((r) => r.total), 1)),
                          angle: -90,
                          position: 'insideLeft',
                          fill: tickStyle.fill,
                          fontSize: 11,
                        }}
                      />
                      <RechartsTooltip {...tipProps} formatter={(v: number) => `${toSafeNumber(v).toFixed(1)} kg CO₂e`} />
                      <Legend {...rechartsLegendProps} />
                      <Bar dataKey="scope1" stackId="scopes" name="Scope 1" fill={GHG_SCOPE_HEX.scope1} {...chartMotion} />
                      <Bar dataKey="scope2" stackId="scopes" name="Scope 2" fill={GHG_SCOPE_HEX.scope2} {...chartMotion} />
                      <Bar dataKey="scope3" stackId="scopes" name="Scope 3" fill={GHG_SCOPE_HEX.scope3} {...chartMotion} />
                    </BarChart>
                  </ResponsiveContainer>
                </Box>
              </CardContent>
            </Card>
          )}
        </Stack>
      )}

      {innerTab === 1 && (
        <Stack spacing={3}>
          <Box>
            <Typography variant="h6" gutterBottom>
              Monthly
            </Typography>
            <TableContainer component={Paper} variant="outlined">
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>Month</TableCell>
                    <TableCell align="right">Actual (kg)</TableCell>
                    <TableCell align="right">Flat target (kg)</TableCell>
                    <TableCell align="right">Variance</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {[...monthlySeries].reverse().map((m) => {
                    const tgt = targetModel.monthlyFlatTarget;
                    const v = m.kg - tgt;
                    return (
                      <TableRow key={m.key}>
                        <TableCell>{formatMonthLabel(m.key)}</TableCell>
                        <TableCell align="right">{m.kg.toFixed(2)}</TableCell>
                        <TableCell align="right">{tgt.toFixed(2)}</TableCell>
                        <TableCell align="right">{v.toFixed(2)}</TableCell>
                      </TableRow>
                    );
                  })}
                  {monthlySeries.length === 0 && (
                    <TableRow>
                      <TableCell colSpan={4} align="center">
                        No monthly data yet.
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </TableContainer>
          </Box>

          <Box>
            <Typography variant="h6" gutterBottom>
              Quarterly
            </Typography>
            <TableContainer component={Paper} variant="outlined">
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>Quarter</TableCell>
                    <TableCell align="right">Actual (kg)</TableCell>
                    <TableCell align="right">Target (kg)</TableCell>
                    <TableCell align="right">% of target</TableCell>
                    <TableCell>Status</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {quarterlyRows.map((r) => (
                    <TableRow key={r.period}>
                      <TableCell>{r.period}</TableCell>
                      <TableCell align="right">{r.actual.toFixed(1)}</TableCell>
                      <TableCell align="right">{r.target.toFixed(1)}</TableCell>
                      <TableCell align="right">{r.progressPct.toFixed(0)}%</TableCell>
                      <TableCell>{r.status}</TableCell>
                    </TableRow>
                  ))}
                  {quarterlyRows.length === 0 && (
                    <TableRow>
                      <TableCell colSpan={5} align="center">
                        No quarterly rollups yet.
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </TableContainer>
          </Box>

          <Box>
            <Typography variant="h6" gutterBottom>
              Half-year
            </Typography>
            <TableContainer component={Paper} variant="outlined">
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>Half-year</TableCell>
                    <TableCell align="right">Actual (kg)</TableCell>
                    <TableCell align="right">Target (kg)</TableCell>
                    <TableCell align="right">% of target</TableCell>
                    <TableCell>Status</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {halfYearRows.map((r) => (
                    <TableRow key={r.period}>
                      <TableCell>{r.period}</TableCell>
                      <TableCell align="right">{r.actual.toFixed(1)}</TableCell>
                      <TableCell align="right">{r.target.toFixed(1)}</TableCell>
                      <TableCell align="right">{r.progressPct.toFixed(0)}%</TableCell>
                      <TableCell>{r.status}</TableCell>
                    </TableRow>
                  ))}
                  {halfYearRows.length === 0 && (
                    <TableRow>
                      <TableCell colSpan={5} align="center">
                        No half-year rollups yet.
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </TableContainer>
          </Box>

          <Box>
            <Typography variant="h6" gutterBottom>
              Annual
            </Typography>
            <TableContainer component={Paper} variant="outlined">
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>Year</TableCell>
                    <TableCell align="right">Actual (kg)</TableCell>
                    <TableCell align="right">Target (kg)</TableCell>
                    <TableCell align="right">% of target</TableCell>
                    <TableCell>Status</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {annualRows.map((r) => (
                    <TableRow key={r.year}>
                      <TableCell>{r.year}</TableCell>
                      <TableCell align="right">{r.actual.toFixed(1)}</TableCell>
                      <TableCell align="right">{r.target.toFixed(1)}</TableCell>
                      <TableCell align="right">{r.progressPct.toFixed(0)}%</TableCell>
                      <TableCell>{r.status}</TableCell>
                    </TableRow>
                  ))}
                  {annualRows.length === 0 && (
                    <TableRow>
                      <TableCell colSpan={5} align="center">
                        No annual rollups yet.
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </TableContainer>
          </Box>
        </Stack>
      )}

      {innerTab === 2 && (
        <Stack spacing={2}>
          <Stack direction="row" alignItems="center" spacing={1}>
            <AutoAwesomeIcon color="secondary" />
            <Typography variant="h6">Recommendations</Typography>
            <Box sx={{ flex: 1 }} />
            <Button
              startIcon={aiLoading ? <CircularProgress size={18} /> : <RefreshIcon />}
              variant="outlined"
              size="small"
              disabled={aiLoading}
              onClick={() => void load()}
            >
              Refresh
            </Button>
          </Stack>

          {aiError && (
            <Alert severity="warning" sx={{ mb: 1 }}>
              {aiError}
            </Alert>
          )}

          <Card variant="outlined">
            <CardContent>
              <Typography variant="subtitle2" gutterBottom>
                Reduction ideas toward your targets
              </Typography>
              {recommendations.length === 0 ? (
                <Typography variant="body2" color="text.secondary">
                  Run assessments and keep transactions classified so tailored reduction suggestions can appear here.
                </Typography>
              ) : (
                <Stack spacing={1.5}>
                  {recommendations.map((rec) => (
                    <Paper key={rec.id} variant="outlined" sx={{ p: 1.5 }}>
                      <Typography variant="subtitle2">{rec.title}</Typography>
                      {rec.description && (
                        <Typography variant="body2" color="text.secondary">
                          {rec.description}
                        </Typography>
                      )}
                      <Stack direction="row" spacing={1} sx={{ mt: 1 }} flexWrap="wrap">
                        {rec.priority && <Chip size="small" label={rec.priority} />}
                        {rec.potentialCO2Reduction != null && rec.potentialCO2Reduction > 0 && (
                          <Chip size="small" color="primary" variant="outlined" label={`~${rec.potentialCO2Reduction} kg Δ`} />
                        )}
                      </Stack>
                    </Paper>
                  ))}
                </Stack>
              )}
            </CardContent>
          </Card>
        </Stack>
      )}
    </Box>
  );
};

export default EmissionsReductionTargets;
