import React from 'react';
import {
  Box,
  Breadcrumbs,
  Chip,
  FormControl,
  InputLabel,
  Link,
  MenuItem,
  Select,
  Tab,
  Tabs,
  Typography,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import { COMPLIANCE_PERIODS, ComplianceSectionDef } from '../../constants/complianceHub';

interface ComplianceTrackShellProps {
  trackTitle: string;
  trackDescription: string;
  trackPath?: '/compliance/india' | '/compliance/export';
  sections: ComplianceSectionDef[];
  activeSection: string;
  onSectionChange: (sectionId: string) => void;
  period: string;
  onPeriodChange: (period: string) => void;
  loading?: boolean;
  children: React.ReactNode;
}

const ComplianceTrackShell: React.FC<ComplianceTrackShellProps> = ({
  trackTitle,
  trackDescription,
  trackPath: _trackPath,
  sections,
  activeSection,
  onSectionChange,
  period,
  onPeriodChange,
  loading,
  children,
}) => {
  const tabIndex = Math.max(
    0,
    sections.findIndex((s) => s.id === activeSection)
  );

  return (
    <Box>
      <Breadcrumbs sx={{ mb: 2 }} aria-label="Compliance navigation">
        <Link component={RouterLink} to="/compliance" underline="hover" color="inherit">
          Compliance
        </Link>
        <Typography color="text.primary">{trackTitle}</Typography>
      </Breadcrumbs>

      <Box
        sx={{
          display: 'flex',
          flexDirection: { xs: 'column', md: 'row' },
          alignItems: { xs: 'stretch', md: 'flex-start' },
          justifyContent: 'space-between',
          gap: 2,
          mb: 2,
        }}
      >
        <Box sx={{ flex: 1, minWidth: 0 }}>
          <Typography variant="h4" component="h1" gutterBottom>
            {trackTitle}
          </Typography>
          <Typography variant="body1" color="text.secondary">
            {trackDescription}
          </Typography>
        </Box>
        <FormControl size="small" sx={{ minWidth: 180 }}>
          <InputLabel id="compliance-period-label">Reporting period</InputLabel>
          <Select
            labelId="compliance-period-label"
            label="Reporting period"
            value={period}
            onChange={(e) => onPeriodChange(e.target.value)}
          >
            {COMPLIANCE_PERIODS.map((p) => (
              <MenuItem key={p.value} value={p.value}>
                {p.label}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
      </Box>

      <Tabs
        value={tabIndex}
        onChange={(_, idx) => onSectionChange(sections[idx]?.id || sections[0].id)}
        variant="scrollable"
        scrollButtons="auto"
        sx={{ mb: 2, borderBottom: 1, borderColor: 'divider' }}
        aria-label={`${trackTitle} sections`}
      >
        {sections.map((section) => (
          <Tab key={section.id} label={section.label} />
        ))}
      </Tabs>

      {loading ? (
        <Chip label="Loading compliance data…" color="info" sx={{ mb: 2 }} />
      ) : null}

      <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 2 }}>
        {sections.find((s) => s.id === activeSection)?.description}
      </Typography>

      {children}
    </Box>
  );
};

export default ComplianceTrackShell;
