import React from 'react';
import ReactDOM from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';
import App from './App';
import ApiService from './services/api';
import { ThemeModeProvider } from './context/ThemeModeContext';
import { NotificationProvider } from './context/NotificationContext';
import { BASELINE_SOFTWARE_VERSION } from './constants/version';

const MINIMUM_LAUNCH_SCREEN_MS = 900;

const rootElement = document.getElementById('root') as HTMLElement;
const root = ReactDOM.createRoot(rootElement);

const setLaunchScreenVersion = (baselineVersion: string) => {
  const versionElement = document.getElementById('launch-screen-version');
  if (versionElement) {
    versionElement.textContent = `Current Baseline Version: ${baselineVersion}`;
  }
};

const loadBaselineVersion = async () => {
  try {
    const versionMetadata = await ApiService.getVersionMetadata();
    return versionMetadata.baselineCodebaseVersion || BASELINE_SOFTWARE_VERSION;
  } catch (error) {
    return BASELINE_SOFTWARE_VERSION;
  }
};

const renderApp = () => {
  root.render(
    <React.StrictMode>
      <BrowserRouter>
        <ThemeModeProvider>
          <NotificationProvider>
            <App />
          </NotificationProvider>
        </ThemeModeProvider>
      </BrowserRouter>
    </React.StrictMode>
  );
};

const startApplication = async () => {
  const launchDelayPromise = new Promise<void>((resolve) => {
    window.setTimeout(resolve, MINIMUM_LAUNCH_SCREEN_MS);
  });

  void loadBaselineVersion().then((baselineVersion) => {
    setLaunchScreenVersion(baselineVersion);
  });

  await launchDelayPromise;
  renderApp();
};

void startApplication();