import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  LinearProgress,
  Stack,
  Typography,
} from '@mui/material';
import { SmartToy as AgentIcon, CheckCircle, RadioButtonUnchecked } from '@mui/icons-material';
import ApiService from '../../services/api';
import { EnterpriseWorkflowSection } from '../../utils/enterpriseWorkflowCompletion';

const EnterpriseWorkflowPlanner: React.FC = () => {
  const [sections, setSections] = useState<EnterpriseWorkflowSection[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeKey, setActiveKey] = useState<string | null>(null);
  const [guidance, setGuidance] = useState<unknown>(null);
  const [orchestrating, setOrchestrating] = useState(false);
  const [message, setMessage] = useState<string | null>(null);

  const loadWorkflow = useCallback(async () => {
    setLoading(true);
    try {
      const response = await ApiService.getEnterpriseWorkflow();
      setSections(response?.data?.sections || []);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadWorkflow();
  }, [loadWorkflow]);

  const completedCount = sections.filter((s) => s.status === 'completed').length;
  const progress = sections.length ? (completedCount / sections.length) * 100 : 0;

  const fetchGuidance = async (sectionKey: string) => {
    setActiveKey(sectionKey);
    setGuidance(null);
    const response = await ApiService.getEnterpriseSectionGuidance(sectionKey);
    setGuidance(response?.data);
  };

  const completeSection = async (sectionKey: string) => {
    await ApiService.completeEnterpriseWorkflowSection(sectionKey);
    await loadWorkflow();
  };

  const runFullOrchestration = async () => {
    setOrchestrating(true);
    setMessage(null);
    try {
      const response = await ApiService.orchestrateEnterpriseEmissions();
      setMessage(response?.data?.summary || 'Orchestration complete');
      await loadWorkflow();
    } catch (err) {
      setMessage(err instanceof Error ? err.message : 'Orchestration failed');
    } finally {
      setOrchestrating(false);
    }
  };

  if (loading) {
    return <LinearProgress />;
  }

  return (
    <Box>
      <Typography variant="h5" sx={{ fontWeight: 700, mb: 1 }}>
        Enterprise compliance workflow
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        AI agents guide each step for SEBI BRSR, GHG boundaries, Scope 3 materiality, PAT, and ICM alignment.
      </Typography>
      <LinearProgress variant="determinate" value={progress} sx={{ mb: 3, height: 8, borderRadius: 1 }} />
      <Stack spacing={2}>
        {sections.map((section) => (
          <Card key={section.key} variant="outlined">
            <CardContent>
              <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 1 }}>
                {section.status === 'completed' ? (
                  <CheckCircle color="success" fontSize="small" />
                ) : (
                  <RadioButtonUnchecked color="action" fontSize="small" />
                )}
                <Typography variant="subtitle1" sx={{ fontWeight: 600, flex: 1 }}>
                  {section.label}
                </Typography>
                <Chip
                  size="small"
                  label={section.status.replace('_', ' ')}
                  color={section.status === 'completed' ? 'success' : 'default'}
                />
              </Stack>
              <Stack direction="row" spacing={1} flexWrap="wrap">
                <Button
                  size="small"
                  startIcon={<AgentIcon />}
                  onClick={() => fetchGuidance(section.key)}
                >
                  Agent guidance
                </Button>
                {section.status !== 'completed' && (
                  <Button size="small" variant="outlined" onClick={() => completeSection(section.key)}>
                    Mark complete
                  </Button>
                )}
              </Stack>
            </CardContent>
          </Card>
        ))}
      </Stack>
      {activeKey && guidance != null ? (
        <Alert severity="info" sx={{ mt: 2 }}>
          <Typography variant="caption" component="pre" sx={{ whiteSpace: 'pre-wrap', m: 0 }}>
            {JSON.stringify(guidance, null, 2)}
          </Typography>
        </Alert>
      ) : null}
      <Button
        variant="contained"
        sx={{ mt: 3 }}
        disabled={orchestrating}
        startIcon={orchestrating ? <CircularProgress size={18} color="inherit" /> : <AgentIcon />}
        onClick={runFullOrchestration}
      >
        Run full multi-agent orchestration
      </Button>
      {message && <Alert severity="success" sx={{ mt: 2 }}>{message}</Alert>}
    </Box>
  );
};

export default EnterpriseWorkflowPlanner;
