import React, { useEffect, useState } from 'react';
import { Navigate, useLocation } from 'react-router-dom';
import ApiService from '../services/api';
import RouteLoadingGate from './RouteLoadingGate';
import { hasCompletedWorkflowPlanner } from '../utils/workflowCompletion';

interface RequireWorkflowPlannerProps {
  children: React.ReactElement;
}

/** Routes where users may finish profile or operations setup without blocking the rest of the app. */
const WORKFLOW_GATE_BYPASS_PREFIXES = ['/msme-profile', '/operations'];

const shouldBypassWorkflowGate = (pathname: string) =>
  WORKFLOW_GATE_BYPASS_PREFIXES.some(
    (prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`)
  );

const RequireWorkflowPlanner: React.FC<RequireWorkflowPlannerProps> = ({ children }) => {
  const location = useLocation();
  const [isLoading, setIsLoading] = useState(true);
  const [redirectPath, setRedirectPath] = useState<string | null>(null);

  useEffect(() => {
    let isMounted = true;

    const checkWorkflowStatus = async () => {
      setIsLoading(true);
      setRedirectPath(null);

      if (shouldBypassWorkflowGate(location.pathname)) {
        if (isMounted) {
          setIsLoading(false);
        }
        return;
      }

      try {
        const response = await ApiService.getMSMEProfile();
        const workflow = response?.data?.business?.manufacturingWorkflow;
        const isWorkflowCompleted = hasCompletedWorkflowPlanner(workflow);

        if (!isWorkflowCompleted && isMounted) {
          setRedirectPath('/operations');
        }
      } catch (error: any) {
        if (!isMounted) {
          return;
        }

        if (error?.message?.toLowerCase().includes('not found')) {
          setRedirectPath('/msme-registration');
        }
      } finally {
        if (isMounted) {
          setIsLoading(false);
        }
      }
    };

    checkWorkflowStatus();

    return () => {
      isMounted = false;
    };
  }, [location.pathname]);

  if (isLoading) {
    return <RouteLoadingGate message="Checking your operations setup…" />;
  }

  if (redirectPath) {
    return <Navigate to={redirectPath} replace state={{ from: location }} />;
  }

  return children;
};

export default RequireWorkflowPlanner;
