export const formatInr = (value: number, currency = 'INR'): string =>
  new Intl.NumberFormat('en-IN', { style: 'currency', currency, maximumFractionDigits: 0 }).format(
    value
  );

export const resolvePlanTierKey = (planId: string): 'starter' | 'growth' | 'enterprise' => {
  if (planId.includes('enterprise')) {
    return 'enterprise';
  }
  if (planId.includes('growth')) {
    return 'growth';
  }
  return 'starter';
};

export const lowestMonthlyPlanInr = (plans: PublicFixedPlan[]): number => {
  const monthly = plans.filter((p) => p.interval === 'monthly').map((p) => p.amountInr);
  if (monthly.length === 0) {
    return plans[0]?.amountInr ?? FALLBACK_PUBLIC_PRICING.fixedPlans[0].amountInr;
  }
  return Math.min(...monthly);
};
