import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  Divider,
  Grid,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Paper,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import {
  ArrowForward as ArrowForwardIcon,
  Business as BusinessIcon,
  Check as CheckIcon,
  Close as CloseIcon,
  Factory as FactoryIcon,
  Payments as PaymentsIcon,
} from '@mui/icons-material';
import { Link as RouterLink } from 'react-router-dom';
import { alpha, useTheme } from '@mui/material/styles';
import apiService from '../services/api';
import {
  FALLBACK_PUBLIC_PRICING,
  FEATURE_COMPARISON_ROWS,
  formatInr,
  PLAN_FEATURE_HIGHLIGHTS,
  PRICING_FAQ,
  PRICING_TEASER,
  PublicFixedPlan,
  PublicPricingData,
  resolvePlanTierKey,
} from '../constants/pricingPlans';

const renderComparisonCell = (value: boolean | string) => {
  if (value === true) {
    return <CheckIcon fontSize="small" color="success" />;
  }
  if (value === false) {
    return <CloseIcon fontSize="small" color="disabled" />;
  }
  return (
    <Typography variant="body2" color="text.secondary">
      {value}
    </Typography>
  );
};

const PricingPage: React.FC = () => {
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';
  const [loading, setLoading] = useState(true);
  const [pricing, setPricing] = useState<PublicPricingData>(FALLBACK_PUBLIC_PRICING);
  const [loadError, setLoadError] = useState<string | null>(null);

  const fetchPricing = useCallback(async () => {
    try {
      setLoading(true);
      setLoadError(null);
      const response = (await apiService.getPublicPricingPlans()) as {
        success?: boolean;
        data?: PublicPricingData;
      };
      if (response?.success && response.data?.fixedPlans?.length) {
        setPricing(response.data);
      } else {
        setPricing(FALLBACK_PUBLIC_PRICING);
      }
    } catch {
      setLoadError('Showing standard plan catalog. Live pricing will load when the API is available.');
      setPricing(FALLBACK_PUBLIC_PRICING);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchPricing();
  }, [fetchPricing]);

  const plans = pricing.fixedPlans;
  const paymentMethodLabels = useMemo(() => {
    const labels: string[] = [];
    if (pricing.paymentMethods?.upi) labels.push('UPI');
    if (pricing.paymentMethods?.cards) labels.push('Cards');
    if (pricing.paymentMethods?.netBanking) labels.push('Net banking');
    return labels.length > 0 ? labels.join(', ') : 'UPI, cards, and net banking (when enabled by admin)';
  }, [pricing.paymentMethods]);

  const renderPlanCard = (plan: PublicFixedPlan) => {
    const tierKey = resolvePlanTierKey(plan.planId);
    const highlights = PLAN_FEATURE_HIGHLIGHTS[tierKey] || [];
    const isPopular = plan.planId === PRICING_TEASER.popularPlanId;
    const intervalLabel = plan.interval === 'yearly' ? 'per year' : 'per month';

    return (
      <Grid item xs={12} sm={6} lg={3} key={plan.planId}>
        <Card
          variant="outlined"
          sx={{
            height: '100%',
            display: 'flex',
            flexDirection: 'column',
            borderColor: isPopular
              ? alpha(theme.palette.primary.main, 0.55)
              : alpha(theme.palette.divider, 0.9),
            boxShadow: isPopular ? theme.shadows[4] : undefined,
            position: 'relative',
          }}
        >
          {isPopular && (
            <Chip
              label="Most popular"
              color="primary"
              size="small"
              sx={{ position: 'absolute', top: 12, right: 12 }}
            />
          )}
          <CardContent sx={{ flex: 1, display: 'flex', flexDirection: 'column', pt: isPopular ? 4.5 : 2 }}>
            <Typography variant="overline" color="text.secondary">
              MSME
            </Typography>
            <Typography variant="h6" sx={{ fontWeight: 800, mb: 0.5 }}>
              {plan.name}
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 2, minHeight: 40 }}>
              {plan.description}
            </Typography>
            <Typography variant="h4" sx={{ fontWeight: 800, color: 'primary.main' }}>
              {formatInr(plan.amountInr, pricing.currency)}
            </Typography>
            <Typography variant="caption" color="text.secondary" sx={{ mb: 2 }}>
              {intervalLabel}
              {pricing.pricesExclusiveOfGst ? ' · excl. GST' : ''}
            </Typography>
            <List dense disablePadding sx={{ mb: 2, flex: 1 }}>
              {highlights.map((item) => (
                <ListItem key={item} disableGutters sx={{ py: 0.35 }}>
                  <ListItemIcon sx={{ minWidth: 28 }}>
                    <CheckIcon fontSize="small" color="primary" />
                  </ListItemIcon>
                  <ListItemText
                    primary={item}
                    primaryTypographyProps={{ variant: 'body2' }}
                  />
                </ListItem>
              ))}
            </List>
            <Button
              component={RouterLink}
              to={`/register?type=msme&plan=${encodeURIComponent(plan.planId)}`}
              variant={isPopular ? 'contained' : 'outlined'}
              fullWidth
              endIcon={<ArrowForwardIcon />}
              sx={
                isPopular
                  ? {
                      background: 'linear-gradient(135deg, #4caf50 0%, #2e7d32 100%)',
                      '&:hover': {
                        background: 'linear-gradient(135deg, #43a047 0%, #1b5e20 100%)',
                      },
                    }
                  : undefined
              }
            >
              Get started
            </Button>
          </CardContent>
        </Card>
      </Grid>
    );
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="40vh">
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box sx={{ pb: 4 }}>
      <Paper
        elevation={0}
        sx={{
          p: { xs: 3, md: 4 },
          mb: 4,
          borderRadius: 3,
          border: `1px solid ${alpha(theme.palette.primary.main, isDark ? 0.28 : 0.18)}`,
          background: isDark
            ? `linear-gradient(145deg, ${alpha(theme.palette.primary.dark, 0.2)} 0%, ${alpha(theme.palette.background.paper, 0.5)} 100%)`
            : 'linear-gradient(135deg, rgba(76, 175, 80, 0.07) 0%, rgba(46, 125, 50, 0.1) 100%)',
        }}
      >
        <Chip label="MSME & enterprise" size="small" color="primary" variant="outlined" sx={{ mb: 2 }} />
        <Typography variant="h4" component="h1" sx={{ fontWeight: 800, mb: 1.5 }}>
          {PRICING_TEASER.headline}
        </Typography>
        <Typography variant="body1" color="text.secondary" sx={{ maxWidth: 820, mb: 2 }}>
          {PRICING_TEASER.subline}
        </Typography>
        {loadError && (
          <Alert severity="info" sx={{ mb: 2 }}>
            {loadError}
          </Alert>
        )}
        {pricing.informationalOnly && (
          <Alert severity="info" icon={<PaymentsIcon />} sx={{ maxWidth: 900 }}>
            {pricing.billingNote}
          </Alert>
        )}
      </Paper>

      <Box component="section" sx={{ mb: 5 }}>
        <Typography variant="h5" sx={{ fontWeight: 700, mb: 0.5 }}>
          MSME fixed plans
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 3, maxWidth: 720 }}>
          Choose a predictable monthly or annual plan. After registration you can review quotes and pay from
          Billing in your workspace.
        </Typography>
        <Grid container spacing={2}>
          {plans.map(renderPlanCard)}
        </Grid>
      </Box>

      <Paper
        variant="outlined"
        sx={{
          p: { xs: 2.5, md: 3 },
          mb: 5,
          borderRadius: 2,
          borderColor: alpha(theme.palette.primary.main, 0.2),
        }}
      >
        <Typography variant="h5" sx={{ fontWeight: 700, mb: 1 }}>
          Usage-based pricing
        </Typography>
        <Typography variant="body1" color="text.secondary" sx={{ mb: 2, maxWidth: 900 }}>
          {pricing.usagePricing.summary}
        </Typography>
        <Grid container spacing={2} sx={{ mb: 2 }}>
          <Grid item xs={12} sm={4}>
            <Typography variant="subtitle2" color="text.secondary">
              Starting from
            </Typography>
            <Typography variant="h5" sx={{ fontWeight: 800, color: 'primary.main' }}>
              {formatInr(pricing.usagePricing.baseAmountInr, pricing.currency)}
            </Typography>
          </Grid>
          <Grid item xs={12} sm={4}>
            <Typography variant="subtitle2" color="text.secondary">
              Typical range
            </Typography>
            <Typography variant="h6" sx={{ fontWeight: 700 }}>
              {formatInr(pricing.usagePricing.typicalRangeInr.min, pricing.currency)}
              {' – '}
              {formatInr(pricing.usagePricing.typicalRangeInr.max, pricing.currency)}
            </Typography>
          </Grid>
          <Grid item xs={12} sm={4}>
            <Typography variant="subtitle2" color="text.secondary">
              Best for
            </Typography>
            <Typography variant="body1">
              Seasonal volumes, growing transaction counts, or complex multi-process workflows.
            </Typography>
          </Grid>
        </Grid>
        <Grid container spacing={1.5}>
          {pricing.usagePricing.factors.map((factor) => (
            <Grid item xs={12} sm={6} key={factor.key}>
              <Box
                sx={{
                  p: 1.5,
                  borderRadius: 1.5,
                  bgcolor: alpha(theme.palette.primary.main, isDark ? 0.08 : 0.04),
                }}
              >
                <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>
                  {factor.label}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  {factor.description}
                </Typography>
              </Box>
            </Grid>
          ))}
        </Grid>
        <Button
          component={RouterLink}
          to="/register?type=msme"
          variant="outlined"
          sx={{ mt: 2.5 }}
          startIcon={<FactoryIcon />}
        >
          Register to see your quote
        </Button>
      </Paper>

      <Box component="section" sx={{ mb: 5 }}>
        <Typography variant="h5" sx={{ fontWeight: 700, mb: 2 }}>
          Compare plan capabilities
        </Typography>
        <TableContainer component={Paper} variant="outlined">
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell sx={{ fontWeight: 700 }}>Feature</TableCell>
                <TableCell align="center" sx={{ fontWeight: 700 }}>
                  Starter
                </TableCell>
                <TableCell align="center" sx={{ fontWeight: 700 }}>
                  Growth
                </TableCell>
                <TableCell align="center" sx={{ fontWeight: 700 }}>
                  Enterprise
                </TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {FEATURE_COMPARISON_ROWS.map((row) => (
                <TableRow key={row.label}>
                  <TableCell>{row.label}</TableCell>
                  <TableCell align="center">{renderComparisonCell(row.starter)}</TableCell>
                  <TableCell align="center">{renderComparisonCell(row.growth)}</TableCell>
                  <TableCell align="center">{renderComparisonCell(row.enterprise)}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      </Box>

      <Paper
        variant="outlined"
        sx={{
          p: { xs: 2.5, md: 3 },
          mb: 5,
          borderRadius: 2,
          bgcolor: alpha(theme.palette.secondary.main, isDark ? 0.06 : 0.03),
        }}
      >
        <Stack direction={{ xs: 'column', md: 'row' }} spacing={3} alignItems={{ md: 'center' }}>
          <Box sx={{ flex: 1 }}>
            <Chip icon={<BusinessIcon />} label="Enterprise & corporations" size="small" sx={{ mb: 1 }} />
            <Typography variant="h5" sx={{ fontWeight: 700, mb: 1 }}>
              Portfolio and supplier programmes
            </Typography>
            <Typography variant="body1" color="text.secondary">
              Enterprise accounts access multi-entity dashboards, value-chain compliance, and BRSR-aligned
              reporting. Commercial terms are tailored to programme size and integration scope.
            </Typography>
          </Box>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.5} flexShrink={0}>
            <Button
              component={RouterLink}
              to="/register?type=enterprise"
              variant="contained"
              color="secondary"
              endIcon={<ArrowForwardIcon />}
            >
              Enterprise register
            </Button>
            <Button component="a" href="mailto:contact@sustainow.in" variant="outlined">
              Contact sales
            </Button>
          </Stack>
        </Stack>
      </Paper>

      <Box component="section" sx={{ mb: 4 }}>
        <Typography variant="h5" sx={{ fontWeight: 700, mb: 2 }}>
          Frequently asked questions
        </Typography>
        <Stack spacing={2}>
          {PRICING_FAQ.map((item) => (
            <Paper key={item.question} variant="outlined" sx={{ p: 2 }}>
              <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 0.75 }}>
                {item.question}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {item.answer}
              </Typography>
            </Paper>
          ))}
        </Stack>
      </Box>

      <Divider sx={{ mb: 3 }} />

      <Stack
        direction={{ xs: 'column', sm: 'row' }}
        spacing={2}
        alignItems={{ xs: 'stretch', sm: 'center' }}
        justifyContent="space-between"
      >
        <Box>
          <Typography variant="subtitle2" color="text.secondary">
            Payments via {pricing.provider === 'razorpay' ? 'Razorpay' : pricing.provider}
          </Typography>
          <Typography variant="body2" color="text.secondary">
            {paymentMethodLabels}
            {pricing.moduleEnabled ? '' : ' · Billing module can be enabled by your administrator'}
          </Typography>
        </Box>
        <Stack direction="row" spacing={1.5} flexWrap="wrap" useFlexGap>
          <Button component={RouterLink} to="/terms-of-service" size="small">
            Terms
          </Button>
          <Button component={RouterLink} to="/privacy-policy" size="small">
            Privacy
          </Button>
          <Button component={RouterLink} to="/register?type=msme" variant="contained" size="large">
            Create MSME account
          </Button>
        </Stack>
      </Stack>
    </Box>
  );
};

export default PricingPage;
